        hvm_vcpu_destroy(v);
    else
        pv_vcpu_destroy(v);
}

v8::Local<v8::Value> WebDOMFileSystem::toV8Value(v8::Local<v8::Object> /* creationContext */, v8::Isolate* isolate)
{
