PictOpValid(CARD8 op)
{
    if ( /*PictOpMinimum <= op && */ op <= PictOpMaximum)
        return TRUE;
    if (PictOpDisjointMinimum <= op && op <= PictOpDisjointMaximum)
        return TRUE;
    if (PictOpConjointMinimum <= op && op <= PictOpConjointMaximum)
        return TRUE;
    if (PictOpBlendMinimum <= op && op <= PictOpBlendMaximum)
        return TRUE;
    return FALSE;
}

int avpriv_ac3_parse_header(AC3HeaderInfo **phdr, const uint8_t *buf,
                            size_t size)
{
    GetBitContext gb;
    AC3HeaderInfo *hdr;
    int err;

    if (!*phdr)
        *phdr = av_mallocz(sizeof(AC3HeaderInfo));
    if (!*phdr)
         return AVERROR(ENOMEM);
     hdr = *phdr;

    err = init_get_bits8(&gb, buf, size);
    if (err < 0)
        return AVERROR_INVALIDDATA;
     err = ff_ac3_parse_header(&gb, hdr);
     if (err < 0)
         return AVERROR_INVALIDDATA;

    return get_bits_count(&gb);
}

static void  Ins_MINDEX( INS_ARG )
{
  Long  L, K;

  L = args[0];

  if (L == 0)
      return;

  if ( L<0 || L > CUR.args )
  {
    CUR.error = TT_Err_Invalid_Reference;
    return;
  }

  K = CUR.stack[CUR.args - L];

  memmove( (&CUR.stack[CUR.args - L    ]),
            (&CUR.stack[CUR.args - L + 1]),
            (L - 1) * sizeof ( Long ) );

  CUR.stack[ CUR.args-1 ] = K;
}

