	RRBNode *entry = _find_entry_submap_node (bank, sm);
	if (!entry) {
		// no intersection with any submap, so just insert
		if (!r_crbtree_insert (bank->submaps, sm, _find_sm_by_from_vaddr_cb, NULL)) {
			free (sm);
			free (mapref);
			return false;
		}
		r_list_append (bank->maprefs, mapref);
		return true;
	}
	bank->last_used = NULL;
	RIOSubMap *bd = (RIOSubMap *)entry->data;
	if (r_io_submap_to (bd) == r_io_submap_to (sm) &&
		r_io_submap_from (bd) >= r_io_submap_from (sm)) {
		// _find_entry_submap_node guarantees, that there is no submap
		// prior to bd in the range of sm, so instead of deleting and inserting
		// we can just memcpy
		memcpy (bd, sm, sizeof (RIOSubMap));
		free (sm);
		r_list_append (bank->maprefs, mapref);
		return true;
	}
	if (r_io_submap_from (bd) < r_io_submap_from (sm) &&
		r_io_submap_to (sm) < r_io_submap_to (bd)) {
		// split bd into 2 maps => bd and bdsm
		RIOSubMap *bdsm = R_NEWCOPY (RIOSubMap, bd);
		if (!bdsm) {
			free (sm);
			free (mapref);
			return false;
		}
		r_io_submap_set_from (bdsm, r_io_submap_to (sm) + 1);
		r_io_submap_set_to (bd, r_io_submap_from (sm) - 1);
		// TODO: insert and check return value, before adjusting sm size
		if (!r_crbtree_insert (bank->submaps, sm, _find_sm_by_from_vaddr_cb, NULL)) {
			free (sm);
			free (bdsm);
			free (mapref);
			return false;
		}
		if (!r_crbtree_insert (bank->submaps, bdsm, _find_sm_by_from_vaddr_cb, NULL)) {
			r_crbtree_delete (bank->submaps, sm, _find_sm_by_from_vaddr_cb, NULL);
			free (sm);
			free (bdsm);
			free (mapref);
			return false;
		}
		r_list_append (bank->maprefs, mapref);
		return true;
	}

	// guaranteed intersection
	if (r_io_submap_from (bd) < r_io_submap_from (sm)) {
		r_io_submap_set_to (bd, r_io_submap_from (sm) - 1);
		entry = r_rbnode_next (entry);
	}
	while (entry && r_io_submap_to (((RIOSubMap *)entry->data)) <= r_io_submap_to (sm)) {
		//delete all submaps that are completly included in sm
		RRBNode *next = r_rbnode_next (entry);
		// this can be optimized, there is no need to do search here
		bool a = r_crbtree_delete (bank->submaps, entry->data, _find_sm_by_from_vaddr_cb, NULL);
		if (!a) {
			break;
		}
		entry = next;
	}
	if (entry && r_io_submap_from (((RIOSubMap *)entry->data)) <= r_io_submap_to (sm)) {
		bd = (RIOSubMap *)entry->data;
		r_io_submap_set_from (bd, r_io_submap_to (sm) + 1);
	}
	if (!r_crbtree_insert (bank->submaps, sm, _find_sm_by_from_vaddr_cb, NULL)) {
		free (sm);
		free (mapref);
		return false;
	}
	r_list_append (bank->maprefs, mapref);
	return true;
}

respond_before:
1. Functional Analysis

- The function begins by looking up a bank and a map by their IDs, aborting and returning false if either is missing.  
- It creates a lightweight reference (`mapref`) to the map, then wraps that in a new submap object (`sm`).  
- It searches the bank’s tree of submaps for any existing submap that overlaps `sm`.  
  - If there is no overlap, it simply inserts `sm` into the tree and records the map reference.  
  - If there is an exact or contained overlap with a single existing submap (`bd`), it updates `bd` in place (via `memcpy`) or splits it into two pieces and inserts the new submap(s).  
- If multiple existing submaps overlap `sm`, it:  
  1. Trims the “left” side of the first overlapping submap so it stops before `sm`.  
  2. Walks forward through the tree, deleting any submaps completely covered by `sm`.  
  3. If the last remaining overlapping submap extends into `sm`, trims its “right” side so it begins just after `sm`.  
  4. Finally, inserts `sm` into the tree and records its map reference.  

2. Vulnerability Analysis

In the overlap-handling loop, the code does this:

    while (entry && r_io_submap_to(entry->data) <= r_io_submap_to(sm)) {
        RRBNode *next = r_rbnode_next(entry);
        bool deleted = r_crbtree_delete(bank->submaps, entry->data, …);
        if (!deleted) break;
        entry = next;
    }
    if (entry && r_io_submap_from(entry->data) <= r_io_submap_to(sm)) {
        /* adjust entry->data */
    }

The call to `r_crbtree_delete` removes and frees the tree node (and possibly its data) associated with `entry`. However, the code holds on to the old `entry` pointer and later advances to `next`, which may itself have been freed or invalidated by the tree delete operation. After the loop, the code unconditionally dereferences `entry->data` to trim the right-hand side of one more overlapping submap. If `entry` refers to a node that was already deleted (or otherwise deallocated) in the loop, then `entry->data` is reading from freed memory. That is a classic use-after-free scenario.

3. Decision

Yes, the code can dereference a tree node or its data after that node has been removed and freed, leading to use-after-free.

