void Compute(OpKernelContext* context) override {
    const Tensor& tensor_in = context->input(0);
    const Tensor& tensor_out = context->input(1);
    const Tensor& out_grad_backprop = context->input(2);

    // For maxpooling3d, tensor_in should have 5 dimensions.
    OP_REQUIRES(context, tensor_in.dims() == 5,
                errors::InvalidArgument("tensor_in must be 5-dimensional"));
    OP_REQUIRES(context, tensor_out.dims() == 5,
                errors::InvalidArgument("tensor_out must be 5-dimensional"));
    // For maxpooling3d, out_grad_backprop should have 5 dimensions.
    OP_REQUIRES(
        context, out_grad_backprop.dims() == 5,
        errors::InvalidArgument("out_grad_backprop must be 5-dimensional"));

    Pool3dParameters params{context,  ksize_,       stride_,
                            padding_, data_format_, tensor_in.shape()};

    Tensor* output = nullptr;
    OP_REQUIRES_OK(context, context->forward_input_or_allocate_output(
                                {2}, 0, tensor_out.shape(), &output));

    // Given access patterns in LaunchMaxPooling3dGradGradOp, these tensors must
    // have elements.
    OP_REQUIRES(context, tensor_in.NumElements() > 0,
                errors::InvalidArgument("received empty tensor tensor_in: ",
                                        tensor_in.DebugString()));
    OP_REQUIRES(context, tensor_out.NumElements() > 0,
                errors::InvalidArgument("received empty tensor tensor_out: ",
                                        tensor_out.DebugString()));
    OP_REQUIRES(
        context, out_grad_backprop.NumElements() > 0,
        errors::InvalidArgument("received empty tensor out_grad_backprop: ",
                                out_grad_backprop.DebugString()));

    LaunchMaxPooling3dGradGradOp<Device, T>::launch(
        context, params, tensor_in, tensor_out, out_grad_backprop, output);
  }

bool pv_map_ldt_shadow_page(unsigned int offset)
{
    struct vcpu *curr = current;
    struct domain *currd = curr->domain;
    struct page_info *page;
    l1_pgentry_t gl1e, *pl1e;
    unsigned long linear = curr->arch.pv.ldt_base + offset;

    BUG_ON(unlikely(in_irq()));

    /*
     * Hardware limit checking should guarantee this property.  NB. This is
     * safe as updates to the LDT can only be made by MMUEXT_SET_LDT to the
     * current vcpu, and vcpu_reset() will block until this vcpu has been
     * descheduled before continuing.
     */
    ASSERT((offset >> 3) <= curr->arch.pv.ldt_ents);

    if ( is_pv_32bit_domain(currd) )
        linear = (uint32_t)linear;

    gl1e = guest_get_eff_kern_l1e(linear);
    if ( unlikely(!(l1e_get_flags(gl1e) & _PAGE_PRESENT)) )
        return false;

    page = get_page_from_gfn(currd, l1e_get_pfn(gl1e), NULL, P2M_ALLOC);
    if ( unlikely(!page) )
        return false;

    if ( unlikely(!get_page_type(page, PGT_seg_desc_page)) )
    {
        put_page(page);
        return false;
    }

    pl1e = &pv_ldt_ptes(curr)[offset >> PAGE_SHIFT];
    l1e_add_flags(gl1e, _PAGE_RW);

#ifdef CONFIG_PV_LDT_PAGING
    spin_lock(&curr->arch.pv.shadow_ldt_lock);
#endif

    l1e_write(pl1e, gl1e);

#ifdef CONFIG_PV_LDT_PAGING
    curr->arch.pv.shadow_ldt_mapcnt++;
    spin_unlock(&curr->arch.pv.shadow_ldt_lock);
#endif

    return true;
}

static vm_fault_t udmabuf_vm_fault(struct vm_fault *vmf)
{
	struct vm_area_struct *vma = vmf->vma;
	struct udmabuf *ubuf = vma->vm_private_data;

	vmf->page = ubuf->pages[vmf->pgoff];
	get_page(vmf->page);
	return 0;
}

int main(int argc, char *argv[])
{
  ros::init(argc, argv, "ntpd_shm");

  ros::NodeHandle nh("~");
  ros::Subscriber time_ref_sub;

  int shm_unit;

  // Override default ROS handler
  signal(SIGINT, sig_handler);

  // Read Parameters
  nh.param("shm_unit", shm_unit, 2);
  nh.param("fixup_date", g_set_date, false);

  // Report settings
  ROS_INFO_STREAM("NTP date fixup: " << ((g_set_date) ? "enabled" : "disabled"));

  g_shm = get_shmTime(shm_unit);
  if (g_shm == NULL)
    return 1;

  // prefer to unreliable connection, but accept tcp too.
  time_ref_sub = nh.subscribe("time_ref", 10, time_ref_cb,
      ros::TransportHints()
      .unreliable().maxDatagramSize(1024)
      .reliable().tcpNoDelay(true));

  ros::spin();
  put_shmTime(&g_shm);
  return 0;
}

static char *
resolveSubtable(const char *table, const char *base, const char *searchPath) {
	char *tableFile;
	static struct stat info;

	if (table == NULL || table[0] == '\0') return NULL;
	tableFile = (char *)malloc(MAXSTRING * sizeof(char) * 2);

	//
	// First try to resolve against base
	//
	if (base) {
		int k;
		strcpy(tableFile, base);
		k = (int)strlen(tableFile);
		while (k >= 0 && tableFile[k] != '/' && tableFile[k] != '\\') k--;
		tableFile[++k] = '\0';
		strcat(tableFile, table);
		if (stat(tableFile, &info) == 0 && !(info.st_mode & S_IFDIR)) {
			_lou_logMessage(LOU_LOG_DEBUG, "found table %s", tableFile);
			return tableFile;
		}
	}

	//
	// It could be an absolute path, or a path relative to the current working
	// directory
	//
	strcpy(tableFile, table);
	if (stat(tableFile, &info) == 0 && !(info.st_mode & S_IFDIR)) {
		_lou_logMessage(LOU_LOG_DEBUG, "found table %s", tableFile);
		return tableFile;
	}

	//
	// Then search `LOUIS_TABLEPATH`, `dataPath` and `programPath`
	//
	if (searchPath[0] != '\0') {
		char *dir;
		int last;
		char *cp;
		char *searchPath_copy = strdup(searchPath);
		for (dir = searchPath_copy;; dir = cp + 1) {
			for (cp = dir; *cp != '\0' && *cp != ','; cp++)
				;
			last = (*cp == '\0');
			*cp = '\0';
			if (dir == cp) dir = ".";
			sprintf(tableFile, "%s%c%s", dir, DIR_SEP, table);
			if (stat(tableFile, &info) == 0 && !(info.st_mode & S_IFDIR)) {
				_lou_logMessage(LOU_LOG_DEBUG, "found table %s", tableFile);
				free(searchPath_copy);
				return tableFile;
			}
			if (last) break;
			sprintf(tableFile, "%s%c%s%c%s%c%s", dir, DIR_SEP, "liblouis", DIR_SEP,
					"tables", DIR_SEP, table);
			if (stat(tableFile, &info) == 0 && !(info.st_mode & S_IFDIR)) {
				_lou_logMessage(LOU_LOG_DEBUG, "found table %s", tableFile);
				free(searchPath_copy);
				return tableFile;
			}
			if (last) break;
		}
		free(searchPath_copy);
	}
	free(tableFile);
	return NULL;
}

void RGBFramebufferModel::load(
  Imf::MultiPartInputFile& file, int partId, bool hasAlpha)
{
    QFuture<void> imageLoading = QtConcurrent::run([this,
                                                    &file,
                                                    partId,
                                                    hasAlpha]() {
        try {
            Imf::InputPart part(file, partId);

            Imath::Box2i datW = part.header().dataWindow();
            m_width           = datW.max.x - datW.min.x + 1;
            m_height          = datW.max.y - datW.min.y + 1;

            m_pixelAspectRatio = part.header().pixelAspectRatio();

            m_dataWindow = QRect(datW.min.x, datW.min.y, m_width, m_height);

            Imath::Box2i dispW = part.header().displayWindow();

            int dispW_width  = dispW.max.x - dispW.min.x + 1;
            int dispW_height = dispW.max.y - dispW.min.y + 1;

            m_displayWindow
              = QRect(dispW.min.x, dispW.min.y, dispW_width, dispW_height);

            // Check if there is specific chromaticities tied to the color
            // representation in this part.
            const Imf::ChromaticitiesAttribute* c
              = part.header().findTypedAttribute<Imf::ChromaticitiesAttribute>(
                "chromaticities");

            Imf::Chromaticities chromaticities;

            if (c != nullptr) {
                chromaticities = c->value();
            }

            m_pixelBuffer = new float[4 * m_width * m_height];

            // Check if there is alpha channel
            if (hasAlpha) {
                std::string      aLayer = m_parentLayer + "A";
                Imf::FrameBuffer framebuffer;

                Imf::Slice aSlice = Imf::Slice::Make(
                  Imf::PixelType::FLOAT,
                  &m_pixelBuffer[3],
                  datW,
                  4 * sizeof(float),
                  4 * m_width * sizeof(float));

                framebuffer.insert(aLayer, aSlice);

                part.setFrameBuffer(framebuffer);
                part.readPixels(datW.min.y, datW.max.y);

            } else {
                for (int y = 0; y < m_height; y++) {
                    for (int x = 0; x < m_width; x++) {
                        m_pixelBuffer[4 * (y * m_width + x) + 3] = 1.f;
                    }
                }
            }

            switch (m_layerType) {
                case Layer_RGB: {
                    std::string rLayer = m_parentLayer + "R";
                    std::string gLayer = m_parentLayer + "G";
                    std::string bLayer = m_parentLayer + "B";

                    Imf::FrameBuffer framebuffer;

                    Imf::Slice rSlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &m_pixelBuffer[0],
                      datW,
                      4 * sizeof(float),
                      4 * m_width * sizeof(float));

                    Imf::Slice gSlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &m_pixelBuffer[1],
                      datW,
                      4 * sizeof(float),
                      4 * m_width * sizeof(float));

                    Imf::Slice bSlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &m_pixelBuffer[2],
                      datW,
                      4 * sizeof(float),
                      4 * m_width * sizeof(float));

                    framebuffer.insert(rLayer, rSlice);
                    framebuffer.insert(gLayer, gSlice);
                    framebuffer.insert(bLayer, bSlice);

                    part.setFrameBuffer(framebuffer);
                    part.readPixels(datW.min.y, datW.max.y);

                    // Handle custom chromaticities
                    Imath::M44f RGB_XYZ = Imf::RGBtoXYZ(chromaticities, 1.f);
                    Imath::M44f XYZ_RGB
                      = Imf::XYZtoRGB(Imf::Chromaticities(), 1.f);

                    Imath::M44f conversionMatrix = RGB_XYZ * XYZ_RGB;

                    #pragma omp parallel for
                    for (int y = 0; y < m_height; y++) {
                        for (int x = 0; x < m_width; x++) {
                            const float r
                              = m_pixelBuffer[4 * (y * m_width + x) + 0];
                            const float g
                              = m_pixelBuffer[4 * (y * m_width + x) + 1];
                            const float b
                              = m_pixelBuffer[4 * (y * m_width + x) + 2];

                            Imath::V3f rgb(r, g, b);
                            rgb *= conversionMatrix;

                            m_pixelBuffer[4 * (y * m_width + x) + 0] = rgb.x;
                            m_pixelBuffer[4 * (y * m_width + x) + 1] = rgb.y;
                            m_pixelBuffer[4 * (y * m_width + x) + 2] = rgb.z;
                        }
                    }
                } break;

                case Layer_YC: {
                    std::string yLayer  = m_parentLayer + "Y";
                    std::string ryLayer = m_parentLayer + "RY";
                    std::string byLayer = m_parentLayer + "BY";

                    Imf::FrameBuffer framebuffer;

                    Imf::Rgba* buff1 = new Imf::Rgba[m_width * m_height];
                    Imf::Rgba* buff2 = new Imf::Rgba[m_width * m_height];

                    float* yBuffer  = new float[m_width * m_height];
                    float* ryBuffer = new float[m_width / 2 * m_height / 2];
                    float* byBuffer = new float[m_width / 2 * m_height / 2];

                    Imf::Slice ySlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &yBuffer[0],
                      datW,
                      sizeof(float),
                      m_width * sizeof(float));

                    Imf::Slice rySlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &ryBuffer[0],
                      datW,
                      sizeof(float),
                      m_width / 2 * sizeof(float),
                      2,
                      2);

                    Imf::Slice bySlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &byBuffer[0],
                      datW,
                      sizeof(float),
                      m_width / 2 * sizeof(float),
                      2,
                      2);

                    framebuffer.insert(yLayer, ySlice);
                    framebuffer.insert(ryLayer, rySlice);
                    framebuffer.insert(byLayer, bySlice);

                    part.setFrameBuffer(framebuffer);
                    part.readPixels(datW.min.y, datW.max.y);

                    // Filling missing values for chroma in the image
                    // TODO: now, naive reconstruction.
                    // Use later Imf::RgbaYca::reconstructChromaHoriz and
                    // Imf::RgbaYca::reconstructChromaVert to reconstruct missing
                    // pixels
                    #pragma omp parallel for
                    for (int y = 0; y < m_height; y++) {
                        for (int x = 0; x < m_width; x++) {
                            const float l = yBuffer[y * m_width + x];

                            /*
                            float ry = 0, by = 0;

                            if (y % 2 == 0) {
                                if (x % 2 == 0) {
                                    ry = ryBuffer[y / 2 * m_width / 2 + x / 2];
                                    by = byBuffer[y / 2 * m_width / 2 + x / 2];
                                } else {
                                    ry = .5 * (ryBuffer[y / 2 * m_width / 2 + x / 2] + ryBuffer[y / 2 * m_width / 2 + x / 2 + 1]);
                                    by = .5 * (byBuffer[y / 2 * m_width / 2 + x / 2] + byBuffer[y / 2 * m_width / 2 + x / 2 + 1]);
                                }
                            } else {
                                if (x % 2 == 0) {
                                    ry = .5 * (ryBuffer[y / 2 * m_width / 2 + x / 2] + ryBuffer[(y / 2 + 1) * m_width / 2 + x / 2]);
                                    by = .5 * (byBuffer[y / 2 * m_width / 2 + x / 2] + byBuffer[(y / 2 + 1) * m_width / 2 + x / 2]);
                                } else {
                                    ry = .25 * (ryBuffer[y / 2 * m_width / 2 + x / 2] + ryBuffer[(y / 2 + 1) * m_width / 2 + x / 2] + ryBuffer[y / 2 * m_width / 2 + x / 2 + 1] + ryBuffer[(y / 2 + 1) * m_width / 2 + x / 2 + 1]);
                                    by = .25 * (byBuffer[y / 2 * m_width / 2 + x / 2] + byBuffer[(y / 2 + 1) * m_width / 2 + x / 2] + byBuffer[y / 2 * m_width / 2 + x / 2 + 1] + byBuffer[(y / 2 + 1) * m_width / 2 + x / 2 + 1]);
                                }
                            }
                            */

                            const float ry
                              = ryBuffer[y / 2 * m_width / 2 + x / 2];
                            const float by
                              = byBuffer[y / 2 * m_width / 2 + x / 2];

                            buff1[y * m_width + x].r = ry;
                            buff1[y * m_width + x].g = l;
                            buff1[y * m_width + x].b = by;
                            // Do not forget the alpha values read earlier
                            buff1[y * m_width + x].a
                              = m_pixelBuffer[4 * (y * m_width + x) + 3];
                        }
                    }

                    Imath::V3f yw = Imf::RgbaYca::computeYw(chromaticities);

                    // Proceed to the YCA -> RGBA conversion
                    #pragma omp parallel for
                    for (int y = 0; y < m_height; y++) {
                        Imf::RgbaYca::YCAtoRGBA(
                          yw,
                          m_width,
                          &buff1[y * m_width],
                          &buff1[y * m_width]);
                    }

                    // Fix over saturated pixels
                    #pragma omp parallel for
                    for (int y = 0; y < m_height; y++) {
                        const Imf::Rgba* scanlines[3];

                        if (y == 0) {
                            scanlines[0] = &buff1[(y + 1) * m_width];
                        } else {
                            scanlines[0] = &buff1[(y - 1) * m_width];
                        }

                        scanlines[1] = &buff1[y * m_width];

                        if (y == m_height - 1) {
                            scanlines[2] = &buff1[(y - 1) * m_width];
                        } else {
                            scanlines[2] = &buff1[(y + 1) * m_width];
                        }

                        Imf::RgbaYca::fixSaturation(
                          yw,
                          m_width,
                          scanlines,
                          &buff2[y * m_width]);
                    }

                    // Handle custom chromaticities
                    Imath::M44f RGB_XYZ = Imf::RGBtoXYZ(chromaticities, 1.f);
                    Imath::M44f XYZ_RGB
                      = Imf::XYZtoRGB(Imf::Chromaticities(), 1.f);

                    Imath::M44f conversionMatrix = RGB_XYZ * XYZ_RGB;

                    #pragma omp parallel for
                    for (int y = 0; y < m_height; y++) {
                        for (int x = 0; x < m_width; x++) {
                            Imath::V3f rgb(
                              buff2[y * m_width + x].r,
                              buff2[y * m_width + x].g,
                              buff2[y * m_width + x].b);

                            rgb = rgb * conversionMatrix;

                            m_pixelBuffer[4 * (y * m_width + x) + 0] = rgb.x;
                            m_pixelBuffer[4 * (y * m_width + x) + 1] = rgb.y;
                            m_pixelBuffer[4 * (y * m_width + x) + 2] = rgb.z;
                        }
                    }

                    delete[] yBuffer;
                    delete[] ryBuffer;
                    delete[] byBuffer;
                    delete[] buff1;
                    delete[] buff2;
                }

                break;

                case Layer_Y: {
                    std::string yLayer = m_parentLayer;

                    Imf::FrameBuffer framebuffer;

                    Imf::Slice ySlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &m_pixelBuffer[0],
                      datW,
                      4 * sizeof(float),
                      4 * m_width * sizeof(float));

                    framebuffer.insert(yLayer, ySlice);

                    part.setFrameBuffer(framebuffer);
                    part.readPixels(datW.min.y, datW.max.y);

                    #pragma omp parallel for
                    for (int i = 0; i < m_height * m_width; i++) {
                        m_pixelBuffer[4 * i + 1] = m_pixelBuffer[4 * i + 0];
                        m_pixelBuffer[4 * i + 2] = m_pixelBuffer[4 * i + 0];
                        m_pixelBuffer[4 * i + 3] = 1.f;
                    }
                } break;
            }

            m_image = QImage(m_width, m_height, QImage::Format_RGBA8888);
            m_isImageLoaded = true;

            emit imageLoaded();

            updateImage();
        } catch (std::exception& e) {
            emit loadFailed(e.what());
            return;
        }
    });

    m_imageLoadingWatcher->setFuture(imageLoading);
}

forward_search_range(regex_t* reg, const UChar* str, const UChar* end, UChar* s,
		     UChar* range, UChar** low, UChar** high, UChar** low_prev)
{
  UChar *p, *pprev = (UChar* )NULL;

#ifdef ONIG_DEBUG_SEARCH
  fprintf(stderr, "forward_search_range: str: %d, end: %d, s: %d, range: %d\n",
	  (int )str, (int )end, (int )s, (int )range);
#endif

  p = s;
  if (reg->dmin > 0) {
    if (ONIGENC_IS_SINGLEBYTE(reg->enc)) {
      p += reg->dmin;
     }
     else {
       UChar *q = p + reg->dmin;

      if (q >= end) return 0; /* fail */
       while (p < q) p += enclen(reg->enc, p);
     }
   }

 retry:
  switch (reg->optimize) {
  case ONIG_OPTIMIZE_EXACT:
    p = slow_search(reg->enc, reg->exact, reg->exact_end, p, end, range);
    break;
  case ONIG_OPTIMIZE_EXACT_IC:
    p = slow_search_ic(reg->enc, reg->case_fold_flag,
                       reg->exact, reg->exact_end, p, end, range);
    break;

  case ONIG_OPTIMIZE_EXACT_BM:
    p = bm_search(reg, reg->exact, reg->exact_end, p, end, range);
    break;

  case ONIG_OPTIMIZE_EXACT_BM_NOT_REV:
    p = bm_search_notrev(reg, reg->exact, reg->exact_end, p, end, range);
    break;

  case ONIG_OPTIMIZE_MAP:
    p = map_search(reg->enc, reg->map, p, range);
    break;
  }

  if (p && p < range) {
    if (p - reg->dmin < s) {
    retry_gate:
      pprev = p;
      p += enclen(reg->enc, p);
      goto retry;
    }

    if (reg->sub_anchor) {
      UChar* prev;

      switch (reg->sub_anchor) {
      case ANCHOR_BEGIN_LINE:
        if (!ON_STR_BEGIN(p)) {
          prev = onigenc_get_prev_char_head(reg->enc,
                                            (pprev ? pprev : str), p);
          if (!ONIGENC_IS_MBC_NEWLINE(reg->enc, prev, end))
            goto retry_gate;
        }
        break;

      case ANCHOR_END_LINE:
        if (ON_STR_END(p)) {
#ifndef USE_NEWLINE_AT_END_OF_STRING_HAS_EMPTY_LINE
          prev = (UChar* )onigenc_get_prev_char_head(reg->enc,
                                                     (pprev ? pprev : str), p);
          if (prev && ONIGENC_IS_MBC_NEWLINE(reg->enc, prev, end))
            goto retry_gate;
#endif
        }
        else if (! ONIGENC_IS_MBC_NEWLINE(reg->enc, p, end)
#ifdef USE_CRNL_AS_LINE_TERMINATOR
                 && ! ONIGENC_IS_MBC_CRNL(reg->enc, p, end)
#endif
                 )
          goto retry_gate;
        break;
      }
    }

    if (reg->dmax == 0) {
      *low = p;
      if (low_prev) {
        if (*low > s)
          *low_prev = onigenc_get_prev_char_head(reg->enc, s, p);
        else
          *low_prev = onigenc_get_prev_char_head(reg->enc,
                                                 (pprev ? pprev : str), p);
      }
    }
    else {
      if (reg->dmax != ONIG_INFINITE_DISTANCE) {
        *low = p - reg->dmax;
        if (*low > s) {
          *low = onigenc_get_right_adjust_char_head_with_prev(reg->enc, s,
                                          *low, (const UChar** )low_prev);
          if (low_prev && IS_NULL(*low_prev))
            *low_prev = onigenc_get_prev_char_head(reg->enc,
                                                   (pprev ? pprev : s), *low);
        }
        else {
          if (low_prev)
            *low_prev = onigenc_get_prev_char_head(reg->enc,
                                                   (pprev ? pprev : str), *low);
        }
      }
    }
    /* no needs to adjust *high, *high is used as range check only */
    *high = p - reg->dmin;

#ifdef ONIG_DEBUG_SEARCH
    fprintf(stderr,
    "forward_search_range success: low: %d, high: %d, dmin: %d, dmax: %d\n",
	    (int )(*low - str), (int )(*high - str), reg->dmin, reg->dmax);
#endif
    return 1; /* success */
  }

  return 0; /* fail */
}

static __u8 *nci_extract_rf_params_nfcf_passive_poll(struct nci_dev *ndev,
			struct rf_tech_specific_params_nfcf_poll *nfcf_poll,
 						     __u8 *data)
 {
 	nfcf_poll->bit_rate = *data++;
	nfcf_poll->sensf_res_len = min_t(__u8, *data++, NFC_SENSF_RES_MAXSIZE);

 	pr_debug("bit_rate %d, sensf_res_len %d\n",
 		 nfcf_poll->bit_rate, nfcf_poll->sensf_res_len);

	memcpy(nfcf_poll->sensf_res, data, nfcf_poll->sensf_res_len);
	data += nfcf_poll->sensf_res_len;

	return data;
}

