static int
GetNumWrongData(const byte * curPtr, const int maxnum)
{
    int count = 0;

    if (1 == maxnum) {
        return (1);
    }
    while (maxnum > count+1 && *(curPtr + count) != *(curPtr + count + 1)) {
        count++;
    }

    return (count);
}

static void
decode_color_temperature(gchar *s, guint16 value)
{
    if (value == 0) {
        g_snprintf(s, ITEM_LABEL_LENGTH, "%u [Mired]", value);
    } else {
        g_snprintf(s, ITEM_LABEL_LENGTH, "%u [Mired] (%u [K])", value, 1000000/value);
    }
    return;
}

void PrepareForInitCacheTest() {
  ASSERT_TRUE(file_util::CreateDirectory(
      file_system_->cache_paths_[GDataRootDirectory::CACHE_TYPE_PERSISTENT]));
  ASSERT_TRUE(file_util::CreateDirectory(
      file_system_->cache_paths_[GDataRootDirectory::CACHE_TYPE_TMP]));
  ASSERT_TRUE(file_util::CreateDirectory(
      file_system_->cache_paths_[GDataRootDirectory::CACHE_TYPE_PINNED]));
  ASSERT_TRUE(file_util::CreateDirectory(
      file_system_->cache_paths_[GDataRootDirectory::CACHE_TYPE_OUTGOING]));


  for (size_t i = 0; i < ARRAYSIZE_UNSAFE(initial_cache_resources); ++i) {
    const struct InitialCacheResource& resource = initial_cache_resources[i];
    FilePath dest_path = file_system_->GetCacheFilePath(
        resource.resource_id,
        resource.md5,
        GDataFile::IsCachePinned(resource.cache_state) ||
            GDataFile::IsCacheDirty(resource.cache_state) ?
                GDataRootDirectory::CACHE_TYPE_PERSISTENT :
                GDataRootDirectory::CACHE_TYPE_TMP,
        GDataFile::IsCacheDirty(resource.cache_state) ?
            GDataFileSystem::CACHED_FILE_LOCALLY_MODIFIED :
            GDataFileSystem::CACHED_FILE_FROM_SERVER);

    if (GDataFile::IsCachePresent(resource.cache_state)) {
      FilePath source_path = GetTestFilePath(resource.source_file);
      ASSERT_TRUE(file_util::CopyFile(source_path, dest_path));
    } else {
      dest_path = FilePath(FILE_PATH_LITERAL(kSymLinkToDevNull));
    }

    if (GDataFile::IsCachePinned(resource.cache_state)) {
      FilePath link_path = file_system_->GetCacheFilePath(
          resource.resource_id,
          "",
          GDataRootDirectory::CACHE_TYPE_PINNED,
          GDataFileSystem::CACHED_FILE_FROM_SERVER);
      ASSERT_TRUE(file_util::CreateSymbolicLink(dest_path, link_path));
    }

    if (GDataFile::IsCacheDirty(resource.cache_state)) {
      FilePath link_path = file_system_->GetCacheFilePath(
          resource.resource_id,
          "",
          GDataRootDirectory::CACHE_TYPE_OUTGOING,
          GDataFileSystem::CACHED_FILE_FROM_SERVER);
      ASSERT_TRUE(file_util::CreateSymbolicLink(dest_path, link_path));
    }
  }
}

status_t FLACParser::init()
{
    mDecoder = FLAC__stream_decoder_new();
 if (mDecoder == NULL) {
        ALOGE("new failed");
 return NO_INIT;
 }
    FLAC__stream_decoder_set_md5_checking(mDecoder, false);
    FLAC__stream_decoder_set_metadata_ignore_all(mDecoder);
    FLAC__stream_decoder_set_metadata_respond(
            mDecoder, FLAC__METADATA_TYPE_STREAMINFO);
    FLAC__stream_decoder_set_metadata_respond(
            mDecoder, FLAC__METADATA_TYPE_PICTURE);
    FLAC__stream_decoder_set_metadata_respond(
            mDecoder, FLAC__METADATA_TYPE_VORBIS_COMMENT);
    FLAC__StreamDecoderInitStatus initStatus;
    initStatus = FLAC__stream_decoder_init_stream(
            mDecoder,
            read_callback, seek_callback, tell_callback,
            length_callback, eof_callback, write_callback,
            metadata_callback, error_callback, (void *) this);
 if (initStatus != FLAC__STREAM_DECODER_INIT_STATUS_OK) {
        ALOGE("init_stream failed %d", initStatus);
 return NO_INIT;
 }
 if (!FLAC__stream_decoder_process_until_end_of_metadata(mDecoder)) {
        ALOGE("end_of_metadata failed");
 return NO_INIT;

     }
     if (mStreamInfoValid) {
        if (getChannels() == 0 || getChannels() > kMaxChannels) {
             ALOGE("unsupported channel count %u", getChannels());
             return NO_INIT;
         }
 switch (getBitsPerSample()) {
 case 8:
 case 16:
 case 24:
 break;
 default:
            ALOGE("unsupported bits per sample %u", getBitsPerSample());
 return NO_INIT;
 }
 switch (getSampleRate()) {
 case 8000:
 case 11025:
 case 12000:
 case 16000:
 case 22050:
 case 24000:
 case 32000:
 case 44100:
 case 48000:
 case 88200:
 case 96000:
 break;
 default:
            ALOGE("unsupported sample rate %u", getSampleRate());
 return NO_INIT;
 }

         static const struct {
             unsigned mChannels;
             unsigned mBitsPerSample;
            void (*mCopy)(short *dst, const int * src[kMaxChannels], unsigned nSamples, unsigned nChannels);
         } table[] = {
             { 1,  8, copyMono8    },
             { 2,  8, copyStereo8  },
 { 8, 8, copyMultiCh8  },
 { 1, 16, copyMono16   },
 { 2, 16, copyStereo16 },
 { 8, 16, copyMultiCh16 },
 { 1, 24, copyMono24   },
 { 2, 24, copyStereo24 },
 { 8, 24, copyMultiCh24 },
 };
 for (unsigned i = 0; i < sizeof(table)/sizeof(table[0]); ++i) {
 if (table[i].mChannels >= getChannels() &&
                    table[i].mBitsPerSample == getBitsPerSample()) {
                mCopy = table[i].mCopy;
 break;
 }
 }
 if (mTrackMetadata != 0) {
            mTrackMetadata->setCString(kKeyMIMEType, MEDIA_MIMETYPE_AUDIO_RAW);
            mTrackMetadata->setInt32(kKeyChannelCount, getChannels());
            mTrackMetadata->setInt32(kKeySampleRate, getSampleRate());
            mTrackMetadata->setInt32(kKeyPcmEncoding, kAudioEncodingPcm16bit);
            mTrackMetadata->setInt64(kKeyDuration,
 (getTotalSamples() * 1000000LL) / getSampleRate());
 }
 } else {
        ALOGE("missing STREAMINFO");
 return NO_INIT;
 }
 if (mFileMetadata != 0) {
        mFileMetadata->setCString(kKeyMIMEType, MEDIA_MIMETYPE_AUDIO_FLAC);
 }
 return OK;
}

