uint8_t _ReadStaticFiles(HTTPReqMessage *req, HTTPResMessage *res) {
	uint8_t found = 0;
	int8_t depth = 0;
	char *uri = req->Header.URI;
	size_t n = strlen(uri);
	size_t i;

	FILE *fp;
	int size;
	char path[128] = {STATIC_FILE_FOLDER};

	char header[] = "HTTP/1.1 200 OK\r\nConnection: close\r\n"
	                "Content-Type: text/html; charset=UTF-8\r\n\r\n";

	/* Prevent Path Traversal. */
	for(i=0; i<n; i++) {
		if(uri[i] == '/') {
			if(((n-i) > 2) && (uri[i+1] == '.') && ((uri[i+2] == '.'))) {
				depth -= 1;
				if(depth < 0)
					break;
			}
			else if (((n-i) > 1) && (uri[i+1] == '.'))
				continue;
			else
				depth += 1;
		}
	}

	if((depth >= 0) && (uri[i-1] != '/')) {
		/* Try to open and load the static file. */
		memcpy(path + strlen(STATIC_FILE_FOLDER), uri, strlen(uri));
		fp = fopen(path, "r");
		if(fp != NULL) {
			fseek(fp, 0, SEEK_END);
			size = ftell(fp);
			fseek(fp, 0, SEEK_SET);

			if(size < MAX_BODY_SIZE) {
				/* Build HTTP OK header. */
				n = strlen(header);
				memcpy(res->_buf, header, n);
				i = n;

				/* Build HTTP body. */
				n = fread(res->_buf + i, 1, size, fp);
				i += n;

				res->_index = i;

				found = 1;
			}
			fclose(fp);
		}
	}

	return found;
}

unsigned HTMLFormElement::formElementIndexWithFormAttribute(Element* element, unsigned rangeStart, unsigned rangeEnd)
{
    if (m_associatedElements.isEmpty())
        return 0;

    ASSERT(rangeStart <= rangeEnd);

    if (rangeStart == rangeEnd)
        return rangeStart;

    unsigned left = rangeStart;
    unsigned right = rangeEnd - 1;
    unsigned short position;

    while (left != right) {
        unsigned middle = left + ((right - left) / 2);
        ASSERT(middle < m_associatedElementsBeforeIndex || middle >= m_associatedElementsAfterIndex);
        position = element->compareDocumentPosition(toHTMLElement(m_associatedElements[middle]));
        if (position & DOCUMENT_POSITION_FOLLOWING)
            right = middle;
        else
            left = middle + 1;
    }

    ASSERT(left < m_associatedElementsBeforeIndex || left >= m_associatedElementsAfterIndex);
    position = element->compareDocumentPosition(toHTMLElement(m_associatedElements[left]));
    if (position & DOCUMENT_POSITION_FOLLOWING)
        return left;
    return left + 1;
}

int hfs_cat_find_brec(struct super_block *sb, u32 cnid,
		      struct hfs_find_data *fd)
{
	hfs_cat_rec rec;
	int res, len, type;

	hfs_cat_build_key(sb, fd->search_key, cnid, NULL);
	res = hfs_brec_read(fd, &rec, sizeof(rec));
	if (res)
		return res;

	type = rec.type;
	if (type != HFS_CDR_THD && type != HFS_CDR_FTH) {
		printk(KERN_ERR "hfs: found bad thread record in catalog\n");
		return -EIO;
	}

	fd->search_key->cat.ParID = rec.thread.ParID;
	len = fd->search_key->cat.CName.len = rec.thread.CName.len;
	memcpy(fd->search_key->cat.CName.name, rec.thread.CName.name, len);
	return hfs_brec_find(fd);
}

static void
bilinear_box_make_weights (PixopsFilterDimension *dim,
			   double                 scale)
{
  int n = ceil (1/scale + 3.0);
  double *pixel_weights = g_new (double, SUBSAMPLE * n);
  double w;
  int offset, i;

  dim->offset = -1.0;
  dim->n = n;
  dim->weights = pixel_weights;

  for (offset = 0; offset < SUBSAMPLE; offset++)
    {
      double x = (double)offset / SUBSAMPLE;
      double a = x + 1 / scale;

      for (i = 0; i < n; i++)
        {
          w  = linear_box_half (0.5 + i - a, 0.5 + i - x);
          w += linear_box_half (1.5 + x - i, 1.5 + a - i);

          *(pixel_weights++) = w * scale;
        }
    }
}

static void mdns_spoof(struct packet_object *po)
 {
    po->flags |= PO_DROPPED; /* Do not forward query */

    struct mdns_header *mdns;
    char name[NS_MAXDNAME];
    int name_len;
    u_char *q, *data, *end;;
    u_int16 class;
    u_int16 type;
    int x;

    mdns = (struct mdns_header *)po->DATA.data;
    data = (u_char *)(mdns+1);
    end = (u_char *)mdns + po->DATA.len;

    q = data;

    if (mdns->flags == 0x8400 || mdns->answer_rrs > 0)
    {
        //We only want queries.
        return;
    }

    /* process all the questions */
    for (x = 0; x < mdns->questions; x++) {

      name_len = dn_expand((u_char*)mdns, end, q, name, sizeof(name));

      q = data + name_len;

      if (q >= end || name_len == 0)
        return;

      NS_GET16(type, q);
      NS_GET16(class, q);

      /* handle only internet class - unmask the QU flag */
      if ((class & ~MDNS_QU_FLAG) != ns_c_in)
         return;

      if(type == ns_t_a) {
         struct ip_addr *reply;
         struct ip_addr *sender;
         struct ip_addr *target;
         u_int8 *tmac;
         u_int8 answer[name_len + 10 + 4];
         u_char *p = answer + name_len;
         char tmp[MAX_ASCII_ADDR_LEN];

         /* found the reply in the list */
         if (get_spoofed_a(name, &reply) != E_SUCCESS)
            return;

         /* check if the family matches the record type */
         if (ntohs(reply->addr_type) != AF_INET) {
            USER_MSG("mdns_spoof: can not spoof A record for %s "
                     "because the value is not a IPv4 address\n", name);
            return;
         }

        /* 
         * in MDNS the original question is not included 
         * into the reply packet as with pure DNS - 
         * fill the buffer with the questioned name of the request
         * we will append the answer just after the quoted name 
         */
         memcpy(answer, data, name_len);                  /* name */
         memcpy(p    , "\x00\x01", 2);                    /* type A */
         memcpy(p + 2, "\x80\x01", 2);                    /* cache-flush-bit + class */
         memcpy(p + 4, "\x00\x00\x0e\x10", 4);            /* TTL (1 hour) */
         memcpy(p + 8, "\x00\x04", 2);                    /* datalen */
         ip_addr_cpy(p + 10, reply);                      /* data */

         /*
          * depending on the MDNS question, the target address has to be redefined;
          * we also can not use the multicast address as the source but also;
          * don't want to reveal our own IP, so the sender needs also be redefined;
          * hence the variables for the transport of the reply need to be prepared.
          */
         prep_mdns_reply(po, class, &sender, &target, &tmac, reply);

         /* send the reply back to the multicast or unicast address 
          * and set the faked address as the source address for the transport
          */
         send_mdns_reply(po->L4.src, sender, target, tmac, 
                         ntohs(mdns->id), answer, sizeof(answer), 1, 0, 0);

         USER_MSG("mdns_spoof: [%s %s] spoofed to [%s]\n", name, type_str(type), ip_addr_ntoa(reply, tmp));
      }
      if(type == ns_t_aaaa) {
         struct ip_addr *reply;
         struct ip_addr *sender;
         struct ip_addr *target;
         u_int8 *tmac;
         u_int8 answer[name_len + 10 + 16];
         u_char *p = answer + name_len;
         char tmp[MAX_ASCII_ADDR_LEN];

         /* found the reply in the list */
         if (get_spoofed_aaaa(name, &reply) != E_SUCCESS)
            return;

         /* check if the family matches the record type */
         if (ntohs(reply->addr_type) != AF_INET6) {
            USER_MSG("mdns_spoof: can not spoof AAAA record for %s "
                     "because the value is not a IPv6 address\n", name);
            return;
         }

        /* 
         * in MDNS the original question is not included 
         * into the reply packet as with pure DNS - 
         * fill the buffer with the questioned name of the request
         * we will append the answer just after the quoted name 
         */
         memcpy(answer, data, name_len);                  /* name */
         memcpy(p    , "\x00\x1c", 2);                    /* type AAAA */
         memcpy(p + 2, "\x80\x01", 2);                    /* cache-flush-bit + class */
         memcpy(p + 4, "\x00\x00\x0e\x10", 4);            /* TTL (1 hour) */
         memcpy(p + 8, "\x00\x10", 2);                    /* datalen */
         ip_addr_cpy(p + 10, reply);                      /* data */

         /*
          * depending on the MDNS question, the target address has to be redefined;
          * we also can not use the multicast address as the source but also;
          * don't want to reveal our own IP, so the sender needs also be redefined;
          * hence the variables for the transport of the reply need to be prepared.
          */
         prep_mdns_reply(po, class, &sender, &target, &tmac, reply);

         /* send the reply back to the multicast or unicast address 
          * and set the faked address as the source address for the transport
          */
         send_mdns_reply(po->L4.src, sender, target, tmac, 
                         ntohs(mdns->id), answer, sizeof(answer), 1, 0, 0);

         USER_MSG("mdns_spoof: [%s %s] spoofed to [%s]\n", name, type_str(type), ip_addr_ntoa(reply, tmp));
       }
       else if (type == ns_t_ptr) {
         struct ip_addr *reply;
         struct ip_addr *sender;
         struct ip_addr *target;
         u_int8 *tmac;
         u_int8 answer[name_len + 256];
         char *a, *p = (char*)answer + name_len;
         int rlen;

         /* found the reply in the list */
         if (get_spoofed_ptr(name, &a, &reply) != E_SUCCESS)
            return;

        /* 
         * in MDNS the original question is not included 
         * into the reply packet as with pure DNS - 
         * fill the buffer with the questioned name of the request
         * we will append the answer just after the quoted name 
         */
         memcpy(answer, data, name_len);                  /* name */
         memcpy(p    , "\x00\x0c", 2);                    /* type PTR */
         memcpy(p + 2, "\x80\x01", 2);                    /* cache-flush-bit + class */
         memcpy(p + 4, "\x00\x00\x0e\x10", 4);            /* TTL (1 hour) */
         /* compress the string into the buffer */
         rlen = dn_comp(a, (u_char*)p + 10, 256, NULL, NULL);
         /* put the length before the dn_comp'd string */
         p += 8;
         NS_PUT16(rlen, p);

         /*
          * depending on the MDNS question, the target address has to be redefined;
          * we also can not use the multicast address as the source but also;
          * don't want to reveal our own IP, so the sender needs also be redefined;
          * hence the variables for the transport of the reply need to be prepared.
          */
         prep_mdns_reply(po, class, &sender, &target, &tmac, reply);

         /* send the fake reply */
         send_mdns_reply(po->L4.src, sender, target, tmac, 
                         ntohs(mdns->id), answer, name_len + 10 + rlen, 1, 0, 0);

         USER_MSG("mdns_spoof: [%s %s] spoofed to [%s]\n", name, type_str(type), a);
      }
      else if (type == ns_t_srv) {
         struct ip_addr *reply;
         struct ip_addr *sender;
         struct ip_addr *target;
         u_int8 *tmac;
         u_int8 answer[name_len + 22 + 12 + 16];
         char *p = (char *)answer + name_len;
         char tmp[MAX_ASCII_ADDR_LEN];
         char srvoffset[2];
         char tgtoffset[2];
         u_int16 port;
         int dn_offset = 0;


         /* found the reply in the list */
         if (get_spoofed_srv(name, &reply, &port) != E_SUCCESS) 
            return;

         /*
          * to refer the target to a proper domain name, we have to strip the
          * service and protocol label from the questioned domain name
          */
         dn_offset += *(data+dn_offset) + 1; /* first label (e.g. _ldap)*/
         dn_offset += *(data+dn_offset) + 1; /* second label (e.g. _tcp) */

         /* avoid offset overrun */
         if (dn_offset + 12 > 255) {
            dn_offset = 0;
         }

         tgtoffset[0] = 0xc0; /* offset byte */
         tgtoffset[1] = 12 + dn_offset; /* offset to the actual domain name */

         /*
          * to inject the spoofed IP address in the additional section, 
          * we have set the offset pointing to the spoofed domain name set 
          * below (in turn, after the domain name [variable length] in the 
          * question section)
          */
         srvoffset[0] = 0xc0; /* offset byte */
         srvoffset[1] = 12 + name_len + 16; /* offset to the answer */

        /* 
         * in MDNS the original question is not included 
         * into the reply packet as with pure DNS - 
         * fill the buffer with the questioned name of the request
         * we will append the answer just after the quoted name 
         */
         memcpy(answer, data, name_len);              /* name */
         memcpy(p    , "\x00\x21", 2);                /* type SRV */
         memcpy(p + 2, "\x80\x01", 2);                /* class IN */
         memcpy(p + 4, "\x00\x00\x0e\x10", 4);        /* TTL (1 hour) */
         memcpy(p + 8, "\x00\x0c", 2);                /* data length */
         memcpy(p + 10, "\x00\x00", 2);               /* priority */
         memcpy(p + 12, "\x00\x00", 2);               /* weight */
         p+=14; 
         NS_PUT16(port, p);                           /* port */ 
         p-=16;             
         /* 
          * add "srv." in front of the stripped domain
          * name and resolve it in the additional 
          * record (here `srvoffset' is pointing at)
          */
         memcpy(p + 16, "\x03\x73\x72\x76", 4);       /* target */
         memcpy(p + 20, tgtoffset,2);                 /* compressed name offset */

         /* add the additional record for the spoofed IPv4 address*/
         if (ntohs(reply->addr_type) == AF_INET) {
             memcpy(p + 22, srvoffset, 2);            /* compressed name offset */
             memcpy(p + 24, "\x00\x01", 2);           /* type A */
             memcpy(p + 26, "\x80\x01", 2);           /* class */
             memcpy(p + 28, "\x00\x00\x0e\x10", 4);   /* TTL (1 hour) */
             memcpy(p + 32, "\x00\x04", 2);           /* datalen */
             ip_addr_cpy(p + 34, reply);              /* data */
             memset(p + 38, 0, 12);                   /* padding */
         }
         /* add the additional record for the spoofed IPv6 address*/
         else if (ntohs(reply->addr_type) == AF_INET6) {
             memcpy(p + 22, srvoffset, 2);            /* compressed name offset */
             memcpy(p + 24, "\x00\x1c", 2);           /* type AAAA */
             memcpy(p + 26, "\x80\x01", 2);           /* class */
             memcpy(p + 28, "\x00\x00\x0e\x10", 4);   /* TTL (1 hour) */
             memcpy(p + 32, "\x00\x10", 2);           /* datalen */
             ip_addr_cpy(p + 34, reply);              /* data */
         }
         else {
             /* IP address not valid - abort */
             return;
         }

         /*
          * depending on the MDNS question, the target address has to be redefined;
          * we also can not use the multicast address as the source but also;
          * don't want to reveal our own IP, so the sender needs also be redefined;
          * hence the variables for the transport of the reply need to be prepared.
          */
         prep_mdns_reply(po, class, &sender, &target, &tmac, reply);

         /* send the reply back to the multicast or unicast address 
          * and set the faked address as the source address for the transport
          */
         send_mdns_reply(po->L4.src, sender, target, tmac, 
                         ntohs(mdns->id), answer, sizeof(answer), 2, 0, 0);

         USER_MSG("mdns_spoof: SRV [%s] spoofed to [%s:%d]\n", name, ip_addr_ntoa(reply, tmp), port);
      }
    }


 }

void operator()(OpKernelContext* context, const Tensor& x_input,
                  const Tensor& scale_input, const Tensor& offset_input,
                  const Tensor& estimated_mean_input,
                  const Tensor& estimated_variance_input,
                  const Tensor* side_input, U epsilon, U exponential_avg_factor,
                  FusedBatchNormActivationMode activation_mode,
                  Tensor* y_output, Tensor* batch_mean_output,
                  Tensor* batch_var_output, Tensor* saved_mean_output,
                  Tensor* saved_var_output, TensorFormat tensor_format,
                  bool use_reserved_space) {
    OP_REQUIRES(context, side_input == nullptr,
                errors::Internal(
                    "The CPU implementation of FusedBatchNorm does not support "
                    "side input."));
    OP_REQUIRES(context,
                activation_mode == FusedBatchNormActivationMode::kIdentity,
                errors::Internal("The CPU implementation of FusedBatchNorm "
                                 "does not support activations."));

    if (use_reserved_space) {
      Tensor* dummy_reserve_space = nullptr;
      OP_REQUIRES_OK(context,
                     context->allocate_output(5, {}, &dummy_reserve_space));
      // Initialize the memory, to avoid sanitizer alerts.
      dummy_reserve_space->flat<U>()(0) = U();
    }
    Tensor transformed_x;
    Tensor transformed_y;
    if (tensor_format == FORMAT_NCHW) {
      const int64 in_batch = GetTensorDim(x_input, tensor_format, 'N');
      const int64 in_rows = GetTensorDim(x_input, tensor_format, 'H');
      const int64 in_cols = GetTensorDim(x_input, tensor_format, 'W');
      const int64 in_depths = GetTensorDim(x_input, tensor_format, 'C');
      OP_REQUIRES_OK(context, context->allocate_temp(
                                  DataTypeToEnum<T>::value,
                                  ShapeFromFormat(FORMAT_NHWC, in_batch,
                                                  in_rows, in_cols, in_depths),
                                  &transformed_x));
      OP_REQUIRES_OK(context, context->allocate_temp(
                                  DataTypeToEnum<T>::value,
                                  ShapeFromFormat(FORMAT_NHWC, in_batch,
                                                  in_rows, in_cols, in_depths),
                                  &transformed_y));
      // Perform NCHW to NHWC
      std::vector<int32> perm = {0, 2, 3, 1};
      OP_REQUIRES_OK(
          context, ::tensorflow::DoTranspose(context->eigen_device<CPUDevice>(),
                                             x_input, perm, &transformed_x));
    } else {
      transformed_x = x_input;
      transformed_y = *y_output;
    }
    typename TTypes<T, 4>::Tensor x(transformed_x.tensor<T, 4>());
    typename TTypes<U>::ConstVec scale(scale_input.vec<U>());
    typename TTypes<U>::ConstVec offset(offset_input.vec<U>());
    typename TTypes<U>::ConstVec estimated_mean(estimated_mean_input.vec<U>());
    typename TTypes<U>::ConstVec estimated_variance(
        estimated_variance_input.vec<U>());
    typename TTypes<T, 4>::Tensor y(transformed_y.tensor<T, 4>());
    typename TTypes<U>::Vec batch_mean(batch_mean_output->vec<U>());
    typename TTypes<U>::Vec batch_variance(batch_var_output->vec<U>());

    const CPUDevice& d = context->eigen_device<CPUDevice>();

    const int depth = x.dimension(3);
    const int size = x.size();
    const int rest_size = size / depth;
    Eigen::DSizes<Eigen::Index, 2> rest_by_depth(rest_size, depth);

#if !defined(EIGEN_HAS_INDEX_LIST)
    Eigen::DSizes<Eigen::Index, 2> one_by_depth(1, depth);
    Eigen::array<int, 1> reduce_dims({0});
    Eigen::array<int, 2> bcast_spec({rest_size, 1});
#else
    Eigen::IndexList<Eigen::type2index<1>, Eigen::Index> one_by_depth;
    one_by_depth.set(1, depth);
    Eigen::IndexList<Eigen::Index, Eigen::type2index<1>> bcast_spec;
    bcast_spec.set(0, rest_size);
#endif

    auto x_rest_by_depth = x.reshape(rest_by_depth).template cast<U>();
    auto x_centered =
        x_rest_by_depth -
        estimated_mean.reshape(one_by_depth).broadcast(bcast_spec);
    auto scaling_factor = ((estimated_variance + epsilon).rsqrt() * scale)
                              .eval()
                              .reshape(one_by_depth)
                              .broadcast(bcast_spec);
    auto x_scaled = x_centered * scaling_factor;
    auto x_shifted =
        (x_scaled + offset.reshape(one_by_depth).broadcast(bcast_spec))
            .template cast<T>();

    y.reshape(rest_by_depth).device(d) = x_shifted;
    batch_mean.device(d) = estimated_mean;
    batch_variance.device(d) = estimated_variance;

    if (tensor_format == FORMAT_NCHW) {
      // Perform NHWC to NCHW
      const std::vector<int32> perm = {0, 3, 1, 2};
      const Status s = ::tensorflow::DoTranspose(
          context->eigen_device<CPUDevice>(), transformed_y, perm, y_output);
      if (!s.ok()) {
        context->SetStatus(errors::InvalidArgument("Transpose failed: ", s));
      }
    }
  }

parse_codes(struct archive_read *a)
{
  int i, j, val, n, r;
  unsigned char bitlengths[MAX_SYMBOLS], zerocount, ppmd_flags;
  unsigned int maxorder;
  struct huffman_code precode;
  struct rar *rar = (struct rar *)(a->format->data);
  struct rar_br *br = &(rar->br);

  free_codes(a);

  /* Skip to the next byte */
  rar_br_consume_unalined_bits(br);

  /* PPMd block flag */
  if (!rar_br_read_ahead(a, br, 1))
    goto truncated_data;
  if ((rar->is_ppmd_block = rar_br_bits(br, 1)) != 0)
  {
    rar_br_consume(br, 1);
    if (!rar_br_read_ahead(a, br, 7))
      goto truncated_data;
    ppmd_flags = rar_br_bits(br, 7);
    rar_br_consume(br, 7);

    /* Memory is allocated in MB */
    if (ppmd_flags & 0x20)
    {
      if (!rar_br_read_ahead(a, br, 8))
        goto truncated_data;
      rar->dictionary_size = (rar_br_bits(br, 8) + 1) << 20;
      rar_br_consume(br, 8);
    }

    if (ppmd_flags & 0x40)
    {
      if (!rar_br_read_ahead(a, br, 8))
        goto truncated_data;
      rar->ppmd_escape = rar->ppmd7_context.InitEsc = rar_br_bits(br, 8);
      rar_br_consume(br, 8);
    }
    else
      rar->ppmd_escape = 2;

    if (ppmd_flags & 0x20)
    {
      maxorder = (ppmd_flags & 0x1F) + 1;
      if(maxorder > 16)
        maxorder = 16 + (maxorder - 16) * 3;

      if (maxorder == 1)
      {
        archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
                          "Truncated RAR file data");
        return (ARCHIVE_FATAL);
      }

      /* Make sure ppmd7_contest is freed before Ppmd7_Construct
       * because reading a broken file cause this abnormal sequence. */
      __archive_ppmd7_functions.Ppmd7_Free(&rar->ppmd7_context);

      rar->bytein.a = a;
      rar->bytein.Read = &ppmd_read;
      __archive_ppmd7_functions.PpmdRAR_RangeDec_CreateVTable(&rar->range_dec);
      rar->range_dec.Stream = &rar->bytein;
      __archive_ppmd7_functions.Ppmd7_Construct(&rar->ppmd7_context);

      if (rar->dictionary_size == 0) {
	      archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
                          "Invalid zero dictionary size");
	      return (ARCHIVE_FATAL);
      }

      if (!__archive_ppmd7_functions.Ppmd7_Alloc(&rar->ppmd7_context,
        rar->dictionary_size))
      {
        archive_set_error(&a->archive, ENOMEM,
                          "Out of memory");
        return (ARCHIVE_FATAL);
      }
      if (!__archive_ppmd7_functions.PpmdRAR_RangeDec_Init(&rar->range_dec))
      {
        archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
                          "Unable to initialize PPMd range decoder");
        return (ARCHIVE_FATAL);
      }
      __archive_ppmd7_functions.Ppmd7_Init(&rar->ppmd7_context, maxorder);
      rar->ppmd_valid = 1;
    }
    else
    {
      if (!rar->ppmd_valid) {
        archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
                          "Invalid PPMd sequence");
        return (ARCHIVE_FATAL);
      }
      if (!__archive_ppmd7_functions.PpmdRAR_RangeDec_Init(&rar->range_dec))
      {
        archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
                          "Unable to initialize PPMd range decoder");
        return (ARCHIVE_FATAL);
      }
    }
  }
  else
  {
    rar_br_consume(br, 1);

    /* Keep existing table flag */
    if (!rar_br_read_ahead(a, br, 1))
      goto truncated_data;
    if (!rar_br_bits(br, 1))
      memset(rar->lengthtable, 0, sizeof(rar->lengthtable));
    rar_br_consume(br, 1);

    memset(&bitlengths, 0, sizeof(bitlengths));
    for (i = 0; i < MAX_SYMBOLS;)
    {
      if (!rar_br_read_ahead(a, br, 4))
        goto truncated_data;
      bitlengths[i++] = rar_br_bits(br, 4);
      rar_br_consume(br, 4);
      if (bitlengths[i-1] == 0xF)
      {
        if (!rar_br_read_ahead(a, br, 4))
          goto truncated_data;
        zerocount = rar_br_bits(br, 4);
        rar_br_consume(br, 4);
        if (zerocount)
        {
          i--;
          for (j = 0; j < zerocount + 2 && i < MAX_SYMBOLS; j++)
            bitlengths[i++] = 0;
        }
      }
    }

    memset(&precode, 0, sizeof(precode));
    r = create_code(a, &precode, bitlengths, MAX_SYMBOLS, MAX_SYMBOL_LENGTH);
    if (r != ARCHIVE_OK) {
      free(precode.tree);
      free(precode.table);
      return (r);
    }

    for (i = 0; i < HUFFMAN_TABLE_SIZE;)
    {
      if ((val = read_next_symbol(a, &precode)) < 0) {
        free(precode.tree);
        free(precode.table);
        return (ARCHIVE_FATAL);
      }
      if (val < 16)
      {
        rar->lengthtable[i] = (rar->lengthtable[i] + val) & 0xF;
        i++;
      }
      else if (val < 18)
      {
        if (i == 0)
        {
          free(precode.tree);
          free(precode.table);
          archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
                            "Internal error extracting RAR file.");
          return (ARCHIVE_FATAL);
        }

        if(val == 16) {
          if (!rar_br_read_ahead(a, br, 3)) {
            free(precode.tree);
            free(precode.table);
            goto truncated_data;
          }
          n = rar_br_bits(br, 3) + 3;
          rar_br_consume(br, 3);
        } else {
          if (!rar_br_read_ahead(a, br, 7)) {
            free(precode.tree);
            free(precode.table);
            goto truncated_data;
          }
          n = rar_br_bits(br, 7) + 11;
          rar_br_consume(br, 7);
        }

        for (j = 0; j < n && i < HUFFMAN_TABLE_SIZE; j++)
        {
          rar->lengthtable[i] = rar->lengthtable[i-1];
          i++;
        }
      }
      else
      {
        if(val == 18) {
          if (!rar_br_read_ahead(a, br, 3)) {
            free(precode.tree);
            free(precode.table);
            goto truncated_data;
          }
          n = rar_br_bits(br, 3) + 3;
          rar_br_consume(br, 3);
        } else {
          if (!rar_br_read_ahead(a, br, 7)) {
            free(precode.tree);
            free(precode.table);
            goto truncated_data;
          }
          n = rar_br_bits(br, 7) + 11;
          rar_br_consume(br, 7);
        }

        for(j = 0; j < n && i < HUFFMAN_TABLE_SIZE; j++)
          rar->lengthtable[i++] = 0;
      }
    }
    free(precode.tree);
    free(precode.table);

    r = create_code(a, &rar->maincode, &rar->lengthtable[0], MAINCODE_SIZE,
                MAX_SYMBOL_LENGTH);
    if (r != ARCHIVE_OK)
      return (r);
    r = create_code(a, &rar->offsetcode, &rar->lengthtable[MAINCODE_SIZE],
                OFFSETCODE_SIZE, MAX_SYMBOL_LENGTH);
    if (r != ARCHIVE_OK)
      return (r);
    r = create_code(a, &rar->lowoffsetcode,
                &rar->lengthtable[MAINCODE_SIZE + OFFSETCODE_SIZE],
                LOWOFFSETCODE_SIZE, MAX_SYMBOL_LENGTH);
    if (r != ARCHIVE_OK)
      return (r);
    r = create_code(a, &rar->lengthcode,
                &rar->lengthtable[MAINCODE_SIZE + OFFSETCODE_SIZE +
                LOWOFFSETCODE_SIZE], LENGTHCODE_SIZE, MAX_SYMBOL_LENGTH);
    if (r != ARCHIVE_OK)
      return (r);
  }

  if (!rar->dictionary_size || !rar->lzss.window)
  {
    /* Seems as though dictionary sizes are not used. Even so, minimize
     * memory usage as much as possible.
     */
    void *new_window;
    unsigned int new_size;

    if (rar->unp_size >= DICTIONARY_MAX_SIZE)
       new_size = DICTIONARY_MAX_SIZE;
     else
       new_size = rar_fls((unsigned int)rar->unp_size) << 1;
     new_window = realloc(rar->lzss.window, new_size);
     if (new_window == NULL) {
       archive_set_error(&a->archive, ENOMEM,
                        "Unable to allocate memory for uncompressed data.");
      return (ARCHIVE_FATAL);
    }
    rar->lzss.window = (unsigned char *)new_window;
    rar->dictionary_size = new_size;
    memset(rar->lzss.window, 0, rar->dictionary_size);
    rar->lzss.mask = rar->dictionary_size - 1;
  }

  rar->start_new_table = 0;
  return (ARCHIVE_OK);
truncated_data:
  archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
                    "Truncated RAR file data");
  rar->valid = 0;
  return (ARCHIVE_FATAL);
}

static int
dissect_connparamrequest(tvbuff_t *tvb, int offset, packet_info *pinfo, proto_tree *tree)
{
    proto_item *item;
    guint16 max_interval, slave_latency;

    item = proto_tree_add_item(tree, hf_btl2cap_min_interval, tvb, offset, 2, ENC_LITTLE_ENDIAN);
    proto_item_append_text(item, " (%g msec)",  tvb_get_letohs(tvb, offset) * 1.25);
    offset += 2;
    item = proto_tree_add_item(tree, hf_btl2cap_max_interval, tvb, offset, 2, ENC_LITTLE_ENDIAN);
    proto_item_append_text(item, " (%g msec)",  tvb_get_letohs(tvb, offset) * 1.25);
    max_interval = tvb_get_letohs(tvb, offset);
    offset += 2;
    item = proto_tree_add_item(tree, hf_btl2cap_slave_latency, tvb, offset, 2, ENC_LITTLE_ENDIAN);
    proto_item_append_text(item, " LL Connection Events");
    slave_latency = tvb_get_letohs(tvb, offset);

    if(slave_latency >= 500 || slave_latency > 10.0 * tvb_get_letohs(tvb, offset + 2) / (max_interval *1.25))
        expert_add_info(pinfo, item, &ei_btl2cap_parameter_mismatch);

    offset += 2;
    item = proto_tree_add_item(tree, hf_btl2cap_timeout_multiplier, tvb, offset, 2, ENC_LITTLE_ENDIAN);
    proto_item_append_text(item, " (%g sec)",  tvb_get_letohs(tvb, offset) * 0.01);
    offset += 2;

    return offset;
}

isofile_free_all_entries(struct iso9660 *iso9660)
{
	struct isofile *file, *file_next;

	file = iso9660->all_file_list.first;
	while (file != NULL) {
