static void
vty_insert_word_overwrite (struct vty *vty, char *str)
{
  size_t nwrite = MIN ((int) strlen (str), VTY_BUFSIZ - vty->cp);
  vty_write (vty, str, nwrite);
  strncpy (&vty->buf[vty->cp], str, nwrite);
  vty->cp += nwrite;
  vty->length = vty->cp;
}

