   command << args["mh_unc"].toString();
   command << args["mh_mountpoint"].toString();
      {
      }

      if (HelperSupport::isStopped())
      {
        proc.kill();
        user_kill = true;
        break;
      }
      else
      {
      }
    }

    if (proc.exitStatus() == KProcess::CrashExit)
    {
      if (!user_kill)
