static void blk_mq_rq_ctx_init(struct request_queue *q, struct blk_mq_ctx *ctx,
			       struct request *rq, unsigned int rw_flags)
{
	if (blk_queue_io_stat(q))
		rw_flags |= REQ_IO_STAT;

	INIT_LIST_HEAD(&rq->queuelist);
	/* csd/requeue_work/fifo_time is initialized before use */
	rq->q = q;
	rq->mq_ctx = ctx;
	rq->cmd_flags |= rw_flags;
	/* do not touch atomic flags, it needs atomic ops against the timer */
	rq->cpu = -1;
	INIT_HLIST_NODE(&rq->hash);
	RB_CLEAR_NODE(&rq->rb_node);
	rq->rq_disk = NULL;
	rq->part = NULL;
	rq->start_time = jiffies;
#ifdef CONFIG_BLK_CGROUP
	rq->rl = NULL;
	set_start_time_ns(rq);
	rq->io_start_time_ns = 0;
#endif
	rq->nr_phys_segments = 0;
#if defined(CONFIG_BLK_DEV_INTEGRITY)
	rq->nr_integrity_segments = 0;
#endif
	rq->special = NULL;
	/* tag was already set */
	rq->errors = 0;

	rq->cmd = rq->__cmd;

	rq->extra_len = 0;
	rq->sense_len = 0;
	rq->resid_len = 0;
	rq->sense = NULL;

	INIT_LIST_HEAD(&rq->timeout_list);
	rq->timeout = 0;

	rq->end_io = NULL;
	rq->end_io_data = NULL;
	rq->next_rq = NULL;

	ctx->rq_dispatched[rw_is_sync(rw_flags)]++;
}

static long __media_device_enum_links(struct media_device *mdev,
				      struct media_links_enum *links)
{
	struct media_entity *entity;

	entity = find_entity(mdev, links->entity);
	if (entity == NULL)
		return -EINVAL;

	if (links->pads) {
		unsigned int p;

 		for (p = 0; p < entity->num_pads; p++) {
 			struct media_pad_desc pad;

			memset(&pad, 0, sizeof(pad));
 			media_device_kpad_to_upad(&entity->pads[p], &pad);
 			if (copy_to_user(&links->pads[p], &pad, sizeof(pad)))
 				return -EFAULT;
		}
	}

	if (links->links) {
		struct media_link_desc __user *ulink;
		unsigned int l;

		for (l = 0, ulink = links->links; l < entity->num_links; l++) {
			struct media_link_desc link;

			/* Ignore backlinks. */
 			if (entity->links[l].source->entity != entity)
 				continue;

			memset(&link, 0, sizeof(link));
 			media_device_kpad_to_upad(entity->links[l].source,
 						  &link.source);
 			media_device_kpad_to_upad(entity->links[l].sink,
						  &link.sink);
			link.flags = entity->links[l].flags;
			if (copy_to_user(ulink, &link, sizeof(*ulink)))
				return -EFAULT;
			ulink++;
		}
	}

	return 0;
}

nfsd_link(struct svc_rqst *rqstp, struct svc_fh *ffhp,
				char *name, int len, struct svc_fh *tfhp)
{
	struct dentry	*ddir, *dnew, *dold;
	struct inode	*dirp;
	__be32		err;
	int		host_err;

	err = fh_verify(rqstp, ffhp, S_IFDIR, NFSD_MAY_CREATE);
	if (err)
		goto out;
	err = fh_verify(rqstp, tfhp, 0, NFSD_MAY_NOP);
	if (err)
		goto out;
	err = nfserr_isdir;
	if (d_is_dir(tfhp->fh_dentry))
		goto out;
	err = nfserr_perm;
	if (!len)
		goto out;
	err = nfserr_exist;
	if (isdotent(name, len))
		goto out;

	host_err = fh_want_write(tfhp);
	if (host_err) {
		err = nfserrno(host_err);
		goto out;
	}

	fh_lock_nested(ffhp, I_MUTEX_PARENT);
	ddir = ffhp->fh_dentry;
	dirp = d_inode(ddir);

	dnew = lookup_one_len(name, ddir, len);
	host_err = PTR_ERR(dnew);
	if (IS_ERR(dnew))
		goto out_nfserr;

	dold = tfhp->fh_dentry;

	err = nfserr_noent;
	if (d_really_is_negative(dold))
		goto out_dput;
	host_err = vfs_link(dold, dirp, dnew, NULL);
	if (!host_err) {
		err = nfserrno(commit_metadata(ffhp));
		if (!err)
			err = nfserrno(commit_metadata(tfhp));
	} else {
		if (host_err == -EXDEV && rqstp->rq_vers == 2)
			err = nfserr_acces;
		else
			err = nfserrno(host_err);
	}
out_dput:
	dput(dnew);
out_unlock:
	fh_unlock(ffhp);
	fh_drop_write(tfhp);
out:
	return err;

out_nfserr:
	err = nfserrno(host_err);
	goto out_unlock;
}

static XML_Bool
storeRawNames(XML_Parser parser) {
  TAG *tag = parser->m_tagStack;
  while (tag) {
    int bufSize;
    int nameLen = sizeof(XML_Char) * (tag->name.strLen + 1);
    char *rawNameBuf = tag->buf + nameLen;
    /* Stop if already stored.  Since m_tagStack is a stack, we can stop
       at the first entry that has already been copied; everything
       below it in the stack is already been accounted for in a
       previous call to this function.
    */
    if (tag->rawName == rawNameBuf)
      break;
    /* For re-use purposes we need to ensure that the
       size of tag->buf is a multiple of sizeof(XML_Char).
    */
    bufSize = nameLen + ROUND_UP(tag->rawNameLength, sizeof(XML_Char));
    if (bufSize > tag->bufEnd - tag->buf) {
      char *temp = (char *)REALLOC(parser, tag->buf, bufSize);
      if (temp == NULL)
        return XML_FALSE;
      /* if tag->name.str points to tag->buf (only when namespace
         processing is off) then we have to update it
      */
      if (tag->name.str == (XML_Char *)tag->buf)
        tag->name.str = (XML_Char *)temp;
      /* if tag->name.localPart is set (when namespace processing is on)
         then update it as well, since it will always point into tag->buf
      */
      if (tag->name.localPart)
        tag->name.localPart
            = (XML_Char *)temp + (tag->name.localPart - (XML_Char *)tag->buf);
      tag->buf = temp;
      tag->bufEnd = temp + bufSize;
      rawNameBuf = temp + nameLen;
    }
    memcpy(rawNameBuf, tag->rawName, tag->rawNameLength);
    tag->rawName = rawNameBuf;
    tag = tag->parent;
  }
  return XML_TRUE;
}

static int handle_send_2(void *object, IP_Port source, const uint8_t *packet, uint16_t length, void *userdata)
{
    Onion *onion = (Onion *)object;

    if (length > ONION_MAX_PACKET_SIZE) {
        return 1;
    }

    if (length <= 1 + SEND_3) {
        return 1;
    }

    change_symmetric_key(onion);

    uint8_t plain[ONION_MAX_PACKET_SIZE];
    uint8_t shared_key[CRYPTO_SHARED_KEY_SIZE];
    get_shared_key(&onion->shared_keys_3, shared_key, dht_get_self_secret_key(onion->dht), packet + 1 + CRYPTO_NONCE_SIZE);
    int len = decrypt_data_symmetric(shared_key, packet + 1, packet + 1 + CRYPTO_NONCE_SIZE + CRYPTO_PUBLIC_KEY_SIZE,
                                     length - (1 + CRYPTO_NONCE_SIZE + CRYPTO_PUBLIC_KEY_SIZE + RETURN_2), plain);

    if (len != length - (1 + CRYPTO_NONCE_SIZE + CRYPTO_PUBLIC_KEY_SIZE + RETURN_2 + CRYPTO_MAC_SIZE)) {
        return 1;
    }

    if (len <= SIZE_IPPORT) {
        return 1;
    }

    if (plain[SIZE_IPPORT] != NET_PACKET_ANNOUNCE_REQUEST &&
            plain[SIZE_IPPORT] != NET_PACKET_ONION_DATA_REQUEST) {
        return 1;
    }

    IP_Port send_to;

    if (ipport_unpack(&send_to, plain, len, 0) == -1) {
        return 1;
    }

    uint8_t data[ONION_MAX_PACKET_SIZE];
    memcpy(data, plain + SIZE_IPPORT, len - SIZE_IPPORT);
    uint16_t data_len = (len - SIZE_IPPORT);
    uint8_t *ret_part = data + (len - SIZE_IPPORT);
    random_nonce(ret_part);
    uint8_t ret_data[RETURN_2 + SIZE_IPPORT];
    ipport_pack(ret_data, &source);
    memcpy(ret_data + SIZE_IPPORT, packet + (length - RETURN_2), RETURN_2);
    len = encrypt_data_symmetric(onion->secret_symmetric_key, ret_part, ret_data, sizeof(ret_data),
                                 ret_part + CRYPTO_NONCE_SIZE);

    if (len != RETURN_3 - CRYPTO_NONCE_SIZE) {
        return 1;
    }

    data_len += RETURN_3;

    if ((uint32_t)sendpacket(onion->net, send_to, data, data_len) != data_len) {
        return 1;
    }

    return 0;
}

void *malloc_wrapper(size_t size, void *caller)
{
    void *ptr = NULL;
#ifdef MBED_MEM_TRACING_ENABLED
    mbed_mem_trace_lock();
#endif
#ifdef MBED_HEAP_STATS_ENABLED
    malloc_stats_mutex->lock();
    alloc_info_t *alloc_info = (alloc_info_t *)SUPER_MALLOC(size + sizeof(alloc_info_t));
    if (alloc_info != NULL) {
        alloc_info->size = size;
        alloc_info->signature = MBED_HEAP_STATS_SIGNATURE;
        ptr = (void *)(alloc_info + 1);
        heap_stats.current_size += size;
        heap_stats.total_size += size;
        heap_stats.alloc_cnt += 1;
        if (heap_stats.current_size > heap_stats.max_size) {
            heap_stats.max_size = heap_stats.current_size;
        }
        heap_stats.overhead_size += MALLOC_HEAP_TOTAL_SIZE(MALLOC_HEADER_PTR(alloc_info)) - size;
    } else {
        heap_stats.alloc_fail_cnt += 1;
    }
    malloc_stats_mutex->unlock();
#else // #ifdef MBED_HEAP_STATS_ENABLED
    ptr = SUPER_MALLOC(size);
#endif // #ifdef MBED_HEAP_STATS_ENABLED
#ifdef MBED_MEM_TRACING_ENABLED
    mbed_mem_trace_malloc(ptr, size, caller);
    mbed_mem_trace_unlock();
#endif // #ifdef MBED_MEM_TRACING_ENABLED
    return ptr;
}

void MultiplayerAPI::_process_rset(Node *p_node, const StringName &p_name, int p_from, const uint8_t *p_packet, int p_packet_len, int p_offset) {

	ERR_EXPLAIN("Invalid packet received. Size too small.");
	ERR_FAIL_COND(p_offset >= p_packet_len);

	// Check that remote can call the RSET on this node.
	RPCMode rset_mode = RPC_MODE_DISABLED;
	const Map<StringName, RPCMode>::Element *E = p_node->get_node_rset_mode(p_name);
	if (E) {
		rset_mode = E->get();
	} else if (p_node->get_script_instance()) {
		rset_mode = p_node->get_script_instance()->get_rset_mode(p_name);
	}

	ERR_EXPLAIN("RSET '" + String(p_name) + "' is not allowed from: " + itos(p_from) + ". Mode is " + itos((int)rset_mode) + ", master is " + itos(p_node->get_network_master()) + ".");
	ERR_FAIL_COND(!_can_call_mode(p_node, rset_mode, p_from));

	Variant value;
	Error err = decode_variant(value, &p_packet[p_offset], p_packet_len - p_offset);

	ERR_EXPLAIN("Invalid packet received. Unable to decode RSET value.");
	ERR_FAIL_COND(err != OK);

	bool valid;

	p_node->set(p_name, value, &valid);
	if (!valid) {
		String error = "Error setting remote property '" + String(p_name) + "', not found in object of type " + p_node->get_class();
		ERR_PRINTS(error);
	}
}

void Compute(OpKernelContext* context) override {
    // Get inputs
    const Tensor& input_tensor = context->input(0);
    const auto input_tensor_flat = input_tensor.flat<int32>();
    const Tensor& input_splits = context->input(1);
    const auto input_splits_flat = input_splits.flat<SPLITS_TYPE>();

    // Since we limit to a 2-D input (flat_values of rank 1 and a single splits
    // tensor), our output dimension will be 1 with it's size equal to the
    // number of splits (outer dimension or ragged tensor).
    TensorShape output_shape({input_splits.dim_size(0) - 1});
    Tensor* output_tensor;
    OP_REQUIRES_OK(context, context->allocate_output("output", output_shape,
                                                     &output_tensor));
    auto output_tensor_flat = output_tensor->flat<tstring>();

    // Use a single index over the flattened input values tensor.
    int idx = 0;
    // Loop through our split dimension to create a new string at each split.
    for (int i = 1; i < input_splits_flat.size(); ++i) {
      icu::UnicodeString unicode_string;
      icu::UnicodeStringAppendable appendable_unicode_string(unicode_string);
      for (; idx < input_splits_flat(i); ++idx) {
        int32 code_point = input_tensor_flat(idx);
        // Check for invalid code point
        if (!U_IS_UNICODE_CHAR(code_point)) {
          if (error_options_.error_on_malformatting) {
            context->CtxFailure(errors::InvalidArgument(
                "Code point is out of range for Unicode, or a noncharacter."));
            return;
          } else if (!error_options_.elide_replacement) {
            code_point = error_options_.subst;
          }
        }
        appendable_unicode_string.appendCodePoint(code_point);
      }
      // Encode our string and save in the output.
      tstring result;
      Encode(encoding_, unicode_string, &result);
      output_tensor_flat(i - 1) = std::move(result);
    }
  }

bool MakeSnippets ( CSphString sIndex, CSphVector<ExcerptQueryChained_t> & dQueries, CSphString & sError, ThdDesc_t & tThd )
{
	SnippetsRemote_t dRemoteSnippets ( dQueries );
	ExcerptQuery_t &q = *dQueries.begin ();

	// Both load_files && load_files_scattered report the absent files as errors.
	// load_files_scattered without load_files just omits the absent files (returns empty strings).
	auto bScattered = !!( q.m_uFilesMode & 2 );
	auto bNeedAllFiles = !!( q.m_uFilesMode & 1 );

	auto pDist = GetDistr ( sIndex );
	if ( pDist )
		for ( auto * pAgent : pDist->m_dAgents )
		{
			auto * pConn = new AgentConn_t;
			pConn->SetMultiAgent ( sIndex, pAgent );
			pConn->m_iMyConnectTimeout = pDist->m_iAgentConnectTimeout;
			pConn->m_iMyQueryTimeout = pDist->m_iAgentQueryTimeout;
			dRemoteSnippets.m_dAgents.Add ( pConn );
		}

	bool bRemote = !dRemoteSnippets.m_dAgents.IsEmpty ();
	if ( bRemote )
	{
		if ( pDist->m_dLocal.GetLength()!=1 )
		{
			sError.SetSprintf ( "%s", "The distributed index for snippets must have exactly one local agent" );
			return false;
		}

		if ( !q.m_uFilesMode )
		{
			sError.SetSprintf ( "%s", "The distributed index for snippets available only when using external files" );
			return false;
		}

		if ( g_iDistThreads<=1 && bScattered )
		{
			sError.SetSprintf ( "%s", "load_files_scattered works only together with dist_threads>1" );
			return false;
		}
		sIndex = *pDist->m_dLocal.begin();
	}

	ServedDescRPtr_c pServed ( GetServed ( sIndex ) );
	if ( !pServed || !pServed->m_pIndex )
	{
		sError.SetSprintf ( "unknown local index '%s' in search request", sIndex.cstr() );
		return false;
	}

	CSphIndex * pIndex = pServed->m_pIndex;
	assert ( pIndex );

	SnippetContext_t tCtx;
	if ( !tCtx.Setup ( pIndex, q, sError ) ) // same path for single - threaded snippets, bail out here on error
		return false;

	///////////////////
	// do highlighting
	///////////////////

	// boring single threaded loop
	StringBuilder_c sErrors ( "; " );
	if ( g_iDistThreads<=1 || dQueries.GetLength()<2 )
	{
		for ( auto & dQuery: dQueries )
		{
			tCtx.BuildExcerpt ( dQuery, pIndex );
			sErrors << dQuery.m_sError;
		}
		sErrors.MoveTo (sError);
		return sError.IsEmpty ();
	}

	// not boring mt loop with (may be) scattered.
	ARRAY_FOREACH ( i, dQueries )
		dQueries[i].m_iSeq = i;

	// collect file sizes; mark absent with EOF_ITEM
	for ( auto & dQuery : dQueries )
	{
		assert ( dQuery.m_iNext == PROCESSED_ITEM );
		if ( dQuery.m_uFilesMode )
		{
			CSphString sFilename, sStatError;
			sFilename.SetSprintf ( "%s%s", g_sSnippetsFilePrefix.cstr(), dQuery.m_sSource.scstr() );
			auto iFileSize = sphGetFileSize (sFilename, &sStatError);
			if ( iFileSize<0 )
			{
				if ( !bScattered )
				{
					sError = sStatError;
					return false;
				}
				dQuery.m_iNext = EOF_ITEM;
			} else
				dQuery.m_iSize = -iFileSize; // so that sort would put bigger ones first
		} else
			dQuery.m_iSize = -dQuery.m_sSource.Length();
	}

	// set correct data size for snippets
	tThd.SetThreadInfo ( R"(snippet datasize=%.1Dk query="%s")",
						 GetSnippetDataSize ( dQueries ), dQueries[0].m_sWords.scstr () );

	// tough jobs first
	if ( !bScattered )
		dQueries.Sort ( bind ( &ExcerptQueryChained_t::m_iSize ) );

	// build list of absent files (that's ok for scattered).
	// later all the list will be sent to remotes (and some of them have to answer)
	int iAbsentHead = EOF_ITEM;
	ARRAY_FOREACH ( i, dQueries )
		if ( dQueries[i].m_iNext==EOF_ITEM )
		{
			dQueries[i].m_iNext = iAbsentHead;
			iAbsentHead = i;
			if ( bNeedAllFiles )
				dQueries[i].m_sError.SetSprintf ( "absenthead: failed to stat %s: %s",
					dQueries[i].m_sSource.cstr(), strerrorm(errno) );
		}

	// check if all files are available locally.
	if ( bScattered && iAbsentHead==EOF_ITEM )
		bRemote = false;

	// stuff for thread-pooling
	auto * pPool = sphThreadPoolCreate ( g_iDistThreads - 1, "snippets", sError );
	if ( !pPool )
		sphWarning ( "failed to create thread_pool, single thread snippets used: %s", sError.cstr () );
	CrashQuery_t tCrashQuery = SphCrashLogger_c::GetQuery (); // transfer query info for crash logger to new thread
	CSphAtomic iCurQuery;
	CSphVector<SnippetJob_t> dThreads ( Min ( 1, g_iDistThreads ) );
	SnippetJob_t * pJobLocal = nullptr;

	// one more boring case: multithreaded, but no remote agents.
	if ( !bRemote )
	{
		// do MT searching
		for ( auto & t : dThreads )
		{
			t.m_iQueries = dQueries.GetLength ();
			t.m_pQueries = dQueries.Begin ();
			t.m_pCurQuery = &iCurQuery;
			t.m_pIndex = pIndex;
			t.m_tCrashQuery = tCrashQuery;
			if ( !pJobLocal )
				pJobLocal = &t;
			else if ( pPool )
				pPool->AddJob ( &t );
		}
		if ( pJobLocal )
			pJobLocal->Call();
		SafeDelete ( pPool );

		// back in query order
		if ( !bScattered )
			dQueries.Sort ( bind ( &ExcerptQueryChained_t::m_iSeq ) );
		dQueries.Apply ( [&] ( const ExcerptQuery_t &dQuery ) { sErrors << dQuery.m_sError; } );
		sErrors.MoveTo ( sError );
		return sError.IsEmpty ();
	}

	// and finally most interesting remote case with possibly scattered.

	int iRemoteAgents = dRemoteSnippets.m_dAgents.GetLength();
	dRemoteSnippets.m_dTasks.Resize ( iRemoteAgents );

	if ( bScattered )
	{
		// on scattered case - just push the chain of absent files to all remotes
		assert ( iAbsentHead!=EOF_ITEM ); // otherwize why we have remotes?
		for ( auto & dTask : dRemoteSnippets.m_dTasks )
			dTask.m_iHead = iAbsentHead;
	} else
	{
		// distribute queries among tasks by total task size
		ARRAY_FOREACH ( i, dQueries )
		{
			auto & dHeadTask = *dRemoteSnippets.m_dTasks.begin();
			dHeadTask.m_iTotal -= dQueries[i].m_iSize; // -= since size stored as negative.
			// queries sheduled for local still have iNext==PROCESSED_ITEM
			dQueries[i].m_iNext = dHeadTask.m_iHead;
			dHeadTask.m_iHead = i;
			dRemoteSnippets.m_dTasks.Sort ( bind ( &SnippetChain_t::m_iTotal ) );
		}
	}

	// do MT searching
	for ( auto &t : dThreads )
	{
		t.m_iQueries = dQueries.GetLength();
		t.m_pQueries = dQueries.Begin();
		t.m_pCurQuery = &iCurQuery;
		t.m_pIndex = pIndex;
		t.m_tCrashQuery = tCrashQuery;
		if ( !pJobLocal )
			pJobLocal = &t;
		else if ( pPool )
			pPool->AddJob ( &t );
	}

	// connect to remote agents and query them
	SnippetRequestBuilder_c tReqBuilder ( &dRemoteSnippets );
	SnippetReplyParser_c tParser ( &dRemoteSnippets );
	CSphRefcountedPtr<RemoteAgentsObserver_i> tReporter ( GetObserver() );
	ScheduleDistrJobs ( dRemoteSnippets.m_dAgents, &tReqBuilder, &tParser, tReporter );

	// run local worker in current thread also
	if ( pJobLocal )
		pJobLocal->Call ();

	// wait local jobs to finish
	SafeDelete ( pPool );

	// wait remotes to finish also
	tReporter->Finish ();

	auto iSuccesses = ( int ) tReporter->GetSucceeded ();
	auto iAgentsDone = ( int ) tReporter->GetFinished ();

	if ( iSuccesses!=dRemoteSnippets.m_dAgents.GetLength() )
	{
		sphWarning ( "Remote snippets: some of the agents didn't answered: %d queried, %d finished, %d succeeded",
			dRemoteSnippets.m_dAgents.GetLength(), iAgentsDone,	iSuccesses );

		if ( !bScattered )
		{
			int iFailed = 0;
			// inverse the success/failed state - so that the queries with negative m_iNext are treated as failed
			dQueries.Apply ( [&] ( ExcerptQueryChained_t &dQuery ) {
				if ( dQuery.m_iNext!=PROCESSED_ITEM )
				{
					dQuery.m_iNext = PROCESSED_ITEM;
					++iFailed;
				} else
					dQuery.m_iNext = 0;
			} );

			// failsafe - one more turn for failed queries on local agent
			if ( iFailed )
			{
				sphWarning ( "Snippets: failsafe for %d failed items", iFailed );
				auto & t = dThreads[0];
				t.m_pQueries = dQueries.Begin();
				iCurQuery = 0;
				t.Call();
			}
		}
	}

	// back in query order
	if ( !bScattered )
		dQueries.Sort ( bind ( &ExcerptQueryChained_t::m_iSeq ) );

	dQueries.Apply ( [&] ( const ExcerptQuery_t &dQuery ) { sErrors << dQuery.m_sError;});
	sErrors.MoveTo ( sError );
	return sError.IsEmpty ();
}

