int fmt_okt_load_song(song_t *song, slurp_t *fp, unsigned int lflags)
{
	uint8_t tag[8];
	unsigned int readflags = 0;
	uint16_t w; // temp for reading
	int plen = 0; // how many positions in the orderlist are valid
	int npat = 0; // next pattern to read
	int nsmp = 1; // next sample (data, not header)
	int pat, sh, sd, e; // iterators (pattern, sample header, sample data, effect warnings
	int nchn = 0; // how many channels does this song use?
	size_t patseek[MAX_PATTERNS] = {0};
	size_t smpseek[MAX_SAMPLES + 1] = {0}; // where the sample's data starts
	uint32_t smpsize[MAX_SAMPLES + 2] = {0}; // data size (one element bigger to simplify loop condition)
	uint32_t smpflag[MAX_SAMPLES + 1] = {0}; // bit width
	uint32_t effwarn = 0; // effect warning mask

	slurp_read(fp, tag, 8);
	if (memcmp(tag, "OKTASONG", 8) != 0)
		return LOAD_UNSUPPORTED;

	while (!slurp_eof(fp)) {
		uint32_t blklen; // length of this block
		size_t nextpos; // ... and start of next one

		slurp_read(fp, tag, 4);
		slurp_read(fp, &blklen, 4);
		blklen = bswapBE32(blklen);
		nextpos = slurp_tell(fp) + blklen;

		switch (OKT_BLOCK(tag[0], tag[1], tag[2], tag[3])) {
		case OKT_BLK_CMOD:
			if (!(readflags & OKT_HAS_CMOD)) {
				readflags |= OKT_HAS_CMOD;
				nchn = okt_read_cmod(song, fp);
			}
			break;
		case OKT_BLK_SAMP:
			if (!(readflags & OKT_HAS_SAMP)) {
				readflags |= OKT_HAS_SAMP;
				okt_read_samp(song, fp, blklen, smpflag);
			}
			break;
		case OKT_BLK_SPEE:
			if (!(readflags & OKT_HAS_SPEE)) {
				readflags |= OKT_HAS_SPEE;
				slurp_read(fp, &w, 2);
				w = bswapBE16(w);
				song->initial_speed = CLAMP(w, 1, 255);
				song->initial_tempo = 125;
			}
			break;
		case OKT_BLK_SLEN:
			// Don't care.
			break;
		case OKT_BLK_PLEN:
			if (!(readflags & OKT_HAS_PLEN)) {
				readflags |= OKT_HAS_PLEN;
				slurp_read(fp, &w, 2);
				plen = bswapBE16(w);
			}
			break;
		case OKT_BLK_PATT:
			if (!(readflags & OKT_HAS_PATT)) {
				readflags |= OKT_HAS_PATT;
				slurp_read(fp, song->orderlist, MIN(blklen, MAX_ORDERS));
			}
			break;
		case OKT_BLK_PBOD:
			/* Need the channel count (in CMOD) in order to read these */
			if (npat < MAX_PATTERNS) {
				if (blklen > 0)
					patseek[npat] = slurp_tell(fp);
				npat++;
			}
			break;
		case OKT_BLK_SBOD:
			if (nsmp < MAX_SAMPLES) {
				smpseek[nsmp] = slurp_tell(fp);
				smpsize[nsmp] = blklen;
				if (smpsize[nsmp])
					nsmp++;
			}
			break;

		default:
			//log_appendf(4, " Warning: Unknown block of type '%c%c%c%c' at 0x%lx",
			//        tag[0], tag[1], tag[2], tag[3], fp->pos - 8);
			break;
		}

		if (slurp_seek(fp, nextpos, SEEK_SET) != 0) {
			log_appendf(4, " Warning: Failed to seek (file truncated?)");
			break;
		}
	}

	if ((readflags & (OKT_HAS_CMOD | OKT_HAS_SPEE)) != (OKT_HAS_CMOD | OKT_HAS_SPEE))
		return LOAD_FORMAT_ERROR;

	if (!(lflags & LOAD_NOPATTERNS)) {
		for (pat = 0; pat < npat; pat++) {
			slurp_seek(fp, patseek[pat], SEEK_SET);
			effwarn |= okt_read_pbod(song, fp, nchn, pat);
		}

		if (effwarn) {
			if (effwarn & 1)
				log_appendf(4, " Warning: Out-of-range effects (junk data?)");
			for (e = 2; e <= 32; e++) {
				if (effwarn & (1 << (e - 1))) {
					log_appendf(4, " Warning: Unimplemented effect %cxx",
						e + (e < 10 ? '0' : ('A' - 10)));
				}
			}
		}
	}

	if (!(lflags & LOAD_NOSAMPLES)) {
		for (sh = sd = 1; sh < MAX_SAMPLES && smpsize[sd]; sh++) {
			song_sample_t *ssmp = song->samples + sh;
			if (!ssmp->length)
				continue;

			if (ssmp->length != smpsize[sd]) {
				log_appendf(4, " Warning: Sample %d: header/data size mismatch (%d/%d)", sh,
					ssmp->length, smpsize[sd]);
				ssmp->length = MIN(smpsize[sd], ssmp->length);
			}

			csf_read_sample(ssmp, SF_BE | SF_M | SF_PCMS | smpflag[sd],
					fp->data + smpseek[sd], ssmp->length);
			sd++;
		}
		// Make sure there's nothing weird going on
		for (; sh < MAX_SAMPLES; sh++) {
			if (song->samples[sh].length) {
				log_appendf(4, " Warning: Sample %d: file truncated", sh);
				song->samples[sh].length = 0;
			}
		}
	}

	song->pan_separation = 64;
	memset(song->orderlist + plen, ORDER_LAST, MAX_ORDERS - plen);
	strcpy(song->tracker_id, "Amiga Oktalyzer");

	return LOAD_SUCCESS;
}

int DCTStream::readMarker() {
  int c;

  do {
    do {
      c = str->getChar();
    } while (c != 0xff && c != EOF);
    while (c == 0xff) {
      c = str->getChar();
    }
  } while (c == 0x00);
  return c;
}

static int r_jwe_aesgcm_key_unwrap(jwe_t * jwe, jwa_alg alg, jwk_t * jwk, int x5u_flags) {
  int ret, res;
  unsigned char iv[96] = {0}, * key = NULL, cipherkey[64] = {0}, tag[128] = {0}, tag_b64url[256] = {0};
  size_t iv_len = 0, key_len = 0, cipherkey_len = 0, tag_b64url_len = 0, tag_len = gnutls_cipher_get_tag_size(r_jwe_get_alg_from_alg(alg));
  unsigned int bits = 0;
  gnutls_datum_t key_g, iv_g;
  gnutls_cipher_hd_t handle = NULL;

  if (r_jwk_key_type(jwk, &bits, x5u_flags) & R_KEY_TYPE_SYMMETRIC && o_strlen(r_jwe_get_header_str_value(jwe, "iv")) && o_strlen(r_jwe_get_header_str_value(jwe, "tag"))) {
    ret = RHN_OK;
    key_len = bits;

    do {
      if ((key = o_malloc(key_len+4)) == NULL) {
        y_log_message(Y_LOG_LEVEL_ERROR, "r_jwe_aesgcm_key_unwrap - Error allocating resources for key");
        ret = RHN_ERROR_MEMORY;
        break;
      }
      if (r_jwk_export_to_symmetric_key(jwk, key, &key_len) != RHN_OK) {
        y_log_message(Y_LOG_LEVEL_ERROR, "r_jwe_aesgcm_key_unwrap - Error r_jwk_export_to_symmetric_key");
        ret = RHN_ERROR;
        break;
      }
      if (!o_base64url_decode((const unsigned char *)r_jwe_get_header_str_value(jwe, "iv"), o_strlen(r_jwe_get_header_str_value(jwe, "iv")), iv, &iv_len)) {
        y_log_message(Y_LOG_LEVEL_ERROR, "r_jwe_aesgcm_key_unwrap - Error o_base64url_decode iv");
        ret = RHN_ERROR_INVALID;
        break;
      }
      if (!o_base64url_decode((const unsigned char *)jwe->encrypted_key_b64url, o_strlen((const char *)jwe->encrypted_key_b64url), cipherkey, &cipherkey_len)) {
        y_log_message(Y_LOG_LEVEL_ERROR, "r_jwe_aesgcm_key_unwrap - Error o_base64url_decode cipherkey");
        ret = RHN_ERROR_INVALID;
        break;
      }
      key_g.data = key;
      key_g.size = key_len;
      iv_g.data = iv;
      iv_g.size = iv_len;
      if ((res = gnutls_cipher_init(&handle, r_jwe_get_alg_from_alg(alg), &key_g, &iv_g))) {
        y_log_message(Y_LOG_LEVEL_ERROR, "r_jwe_aesgcm_key_unwrap - Error gnutls_cipher_init: '%s'", gnutls_strerror(res));
        ret = RHN_ERROR_INVALID;
        break;
      }
      if ((res = gnutls_cipher_decrypt(handle, cipherkey, cipherkey_len))) {
        y_log_message(Y_LOG_LEVEL_ERROR, "r_jwe_aesgcm_key_unwrap - Error gnutls_cipher_decrypt: '%s'", gnutls_strerror(res));
        ret = RHN_ERROR;
        break;
      }
      if ((res = gnutls_cipher_tag(handle, tag, tag_len))) {
        y_log_message(Y_LOG_LEVEL_ERROR, "r_jwe_aesgcm_key_unwrap - Error gnutls_cipher_tag: '%s'", gnutls_strerror(res));
        ret = RHN_ERROR;
        break;
      }
      if (!o_base64url_encode(tag, tag_len, tag_b64url, &tag_b64url_len)) {
        y_log_message(Y_LOG_LEVEL_ERROR, "r_jwe_aesgcm_key_unwrap - Error o_base64url_encode tag");
        ret = RHN_ERROR;
        break;
      }
      tag_b64url[tag_b64url_len] = '\0';
      if (0 != o_strcmp((const char *)tag_b64url, r_jwe_get_header_str_value(jwe, "tag"))) {
        y_log_message(Y_LOG_LEVEL_ERROR, "r_jwe_aesgcm_key_unwrap - Invalid tag %s %s", tag_b64url, r_jwe_get_header_str_value(jwe, "tag"));
        ret = RHN_ERROR_INVALID;
        break;
      }
      if (r_jwe_set_cypher_key(jwe, cipherkey, cipherkey_len) != RHN_OK) {
        y_log_message(Y_LOG_LEVEL_ERROR, "r_jwe_aesgcm_key_unwrap - Error r_jwe_set_cypher_key");
        ret = RHN_ERROR;
      }

    } while (0);
    o_free(key);
    if (handle != NULL) {
      gnutls_cipher_deinit(handle);
    }
  } else {
    y_log_message(Y_LOG_LEVEL_ERROR, "r_jwe_aesgcm_key_unwrap - Error invalid key");
    ret = RHN_ERROR_INVALID;
  }
  return ret;
}

static int udf_encode_fh(struct inode *inode, __u32 *fh, int *lenp,
			 struct inode *parent)
{
	int len = *lenp;
	struct kernel_lb_addr location = UDF_I(inode)->i_location;
	struct fid *fid = (struct fid *)fh;
	int type = FILEID_UDF_WITHOUT_PARENT;

	if (parent && (len < 5)) {
		*lenp = 5;
		return 255;
	} else if (len < 3) {
		*lenp = 3;
		return 255;
	}

 	*lenp = 3;
 	fid->udf.block = location.logicalBlockNum;
 	fid->udf.partref = location.partitionReferenceNum;
	fid->udf.parent_partref = 0;
 	fid->udf.generation = inode->i_generation;

 	if (parent) {
		location = UDF_I(parent)->i_location;
		fid->udf.parent_block = location.logicalBlockNum;
		fid->udf.parent_partref = location.partitionReferenceNum;
		fid->udf.parent_generation = inode->i_generation;
		*lenp = 5;
		type = FILEID_UDF_WITH_PARENT;
	}

	return type;
}

static inline loff_t ext4_isize(struct ext4_inode *raw_inode)
{
	if (S_ISREG(le16_to_cpu(raw_inode->i_mode)))
		return ((loff_t)le32_to_cpu(raw_inode->i_size_high) << 32) |
			le32_to_cpu(raw_inode->i_size_lo);
	else
		return (loff_t) le32_to_cpu(raw_inode->i_size_lo);
}

__attribute__((__always_inline__)) static inline void create_v4_hdr(
    struct iphdr* iph,
    __u8 tos,
    __u32 saddr,
    __u32 daddr,
    __u16 pkt_bytes,
    __u8 proto) {
  __u64 csum = 0;
  iph->version = 4;
  iph->ihl = 5;
  iph->frag_off = 0;
  iph->protocol = proto;
  iph->check = 0;
#ifdef COPY_INNER_PACKET_TOS
  iph->tos = tos;
#else
  iph->tos = DEFAULT_TOS;
#endif
  iph->tot_len = bpf_htons(pkt_bytes + sizeof(struct iphdr));
  iph->id = 0;
  iph->daddr = daddr;
  iph->saddr = saddr;
  iph->ttl = DEFAULT_TTL;
  ipv4_csum_inline(iph, &csum);
  iph->check = csum;
}

